#include <csignal>
#include <cstring>
#include <exception>
#include <iostream>
#include <memory>
#include <sstream>
#include <string>
#include <utility>
#include <unistd.h>

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "mutual-targets-destroyed",
    "three-way-cycle-destroyed",
    "self-target-destroyed",
    "attack-live-target-log",
    "dead-target-destroyed-immediately",
    "attack-expired-target-safe",
    "attack-without-target-safe",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// A crash in learner code must still produce one line per remaining case.
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (유효하지 않은 타겟 역참조 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

// Redirects std::cout into a string while alive.
struct Capture {
    std::ostringstream oss;
    std::streambuf* old;
    Capture() : old(std::cout.rdbuf(oss.rdbuf())) {}
    ~Capture() { std::cout.rdbuf(old); }
    std::string Text() const { return oss.str(); }
};

bool Has(const std::string& log, const char* needle) {
    return log.find(needle) != std::string::npos;
}

// Each case returns an empty string on success, otherwise a short reason.
std::string MutualTargets() {
    Capture cap;
    std::weak_ptr<Monster> wa, wb;
    {
        auto a = std::make_shared<Monster>("Orc");
        auto b = std::make_shared<Monster>("Knight");
        a->SetTarget(b);
        b->SetTarget(a);
        wa = a;
        wb = b;
    }
    if (!wa.expired() || !wb.expired()) return "서로를 타겟으로 지정한 두 몬스터가 스코프 종료 후에도 살아 있음";
    const std::string log = cap.Text();
    if (!Has(log, "Orc destroyed") || !Has(log, "Knight destroyed")) return "destroyed 로그가 출력되지 않음";
    return "";
}

std::string ThreeWayCycle() {
    Capture cap;
    std::weak_ptr<Monster> wa, wb, wc;
    {
        auto a = std::make_shared<Monster>("A");
        auto b = std::make_shared<Monster>("B");
        auto c = std::make_shared<Monster>("C");
        a->SetTarget(b);
        b->SetTarget(c);
        c->SetTarget(a);
        wa = a;
        wb = b;
        wc = c;
    }
    if (!wa.expired() || !wb.expired() || !wc.expired()) return "A->B->C->A 고리의 몬스터가 파괴되지 않음";
    return "";
}

std::string SelfTarget() {
    Capture cap;
    std::weak_ptr<Monster> w;
    {
        auto m = std::make_shared<Monster>("Mimic");
        m->SetTarget(m);
        w = m;
    }
    if (!w.expired()) return "자기 자신을 타겟으로 지정한 몬스터가 파괴되지 않음";
    return "";
}

std::string AttackLiveTarget() {
    Capture cap;
    auto orc = std::make_shared<Monster>("Orc");
    auto knight = std::make_shared<Monster>("Knight");
    orc->SetTarget(knight);
    orc->Attack();
    if (!Has(cap.Text(), "Orc attacks Knight")) return "살아 있는 타겟 공격 시 'Orc attacks Knight' 로그가 없음";
    return "";
}

std::string DeadTargetDestroyedImmediately() {
    Capture cap;
    auto orc = std::make_shared<Monster>("Orc");
    auto knight = std::make_shared<Monster>("Knight");
    std::weak_ptr<Monster> wk = knight;
    orc->SetTarget(knight);
    knight.reset();
    if (!wk.expired()) return "소유자가 놓은 타겟을 공격자가 붙잡고 있어 파괴되지 않음";
    if (!Has(cap.Text(), "Knight destroyed")) return "타겟 파괴 시점에 destroyed 로그가 없음";
    return "";
}

std::string AttackExpiredTarget() {
    Capture cap;
    auto orc = std::make_shared<Monster>("Orc");
    auto knight = std::make_shared<Monster>("Knight");
    orc->SetTarget(knight);
    knight.reset();
    orc->Attack();
    if (Has(cap.Text(), "Orc attacks")) return "이미 파괴되었어야 할 타겟을 공격함";
    return "";
}

std::string AttackWithoutTarget() {
    Capture cap;
    auto solo = std::make_shared<Monster>("Solo");
    solo->Attack();
    if (Has(cap.Text(), "Solo attacks")) return "타겟이 없는데 공격 로그가 출력됨";
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    MutualTargets, ThreeWayCycle, SelfTarget, AttackLiveTarget,
    DeadTargetDestroyedImmediately, AttackExpiredTarget, AttackWithoutTarget,
};

}  // namespace judge

int main() {
    using namespace judge;
    const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
    for (int s : signals) std::signal(s, OnCrash);

    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        std::string reason;
        try {
            reason = kFns[i]();
        } catch (const std::exception&) {
            reason = "예외가 밖으로 전파됨 (만료된 weak_ptr로 shared_ptr을 직접 생성했을 가능성)";
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                          : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
        line += "\n";
        Emit(line.c_str());
    }
    return 0;
}

