problems.solutionCode:
#include <cstddef>
#include <cstdint>
#include <vector>

// Cold data: touched only on hit, expiry, or debugging.
struct ProjectileCold {
    float damage;
    float lifetime;
    std::uint32_t ownerId;
    std::uint32_t skillId;
    std::uint32_t teamMask;
    std::uint32_t flags;
    char debugName[16];
};
static_assert(sizeof(ProjectileCold) == 40, "cold part is 40 bytes");

// Hot data as SoA: one contiguous float array per field.
// Invariant: every vector has the same size; index i is one projectile.
struct ProjectileStore {
    std::vector<float> px, py, pz;
    std::vector<float> vx, vy, vz;
    std::vector<ProjectileCold> cold;

    std::size_t Size() const { return px.size(); }

    void Add(float x, float y, float z,
             float velX, float velY, float velZ,
             const ProjectileCold& c) {
        px.push_back(x);  py.push_back(y);  pz.push_back(z);
        vx.push_back(velX); vy.push_back(velY); vz.push_back(velZ);
        cold.push_back(c);
    }

    // O(1) removal: overwrite slot i with the last element in EVERY array.
    // Order is not preserved, and index i now refers to a different projectile.
    void RemoveSwapBack(std::size_t i) {
        px[i] = px.back(); px.pop_back();
        py[i] = py.back(); py.pop_back();
        pz[i] = pz.back(); pz.pop_back();
        vx[i] = vx.back(); vx.pop_back();
        vy[i] = vy.back(); vy.pop_back();
        vz[i] = vz.back(); vz.pop_back();
        cold[i] = cold.back(); cold.pop_back();
    }
};

// Hot loop: reads/writes only the six float arrays (24 bytes per projectile).
void UpdateProjectiles(ProjectileStore& s, float dt) {
    const std::size_t n = s.Size();
    for (std::size_t i = 0; i < n; ++i) {
        s.px[i] += s.vx[i] * dt;
        s.py[i] += s.vy[i] * dt;
        s.pz[i] += s.vz[i] * dt;
    }
}

#include <iostream>
#include <string>
#include <utility>
#include <vector>

struct Tracer {
    Tracer() = default;
    Tracer(const Tracer&) { std::cout << "copy\n"; }
    Tracer(Tracer&&) noexcept { std::cout << "move\n"; }
};

struct ThrowingMove {
    ThrowingMove() = default;
    ThrowingMove(const ThrowingMove&) { std::cout << "copy\n"; }
    ThrowingMove(ThrowingMove&&) { std::cout << "move\n"; }   // not noexcept
};

int main() {
    const Tracer c{};
    Tracer a = std::move(c);        // prints "copy": const Tracer&& cannot bind to Tracer&&

    std::vector<Tracer> good(1);
    good.reserve(good.capacity() + 1);      // reallocation prints "move"

    std::vector<ThrowingMove> bad(1);
    bad.reserve(bad.capacity() + 1);        // reallocation prints "copy"

    (void)a;
    return 0;
}

