#include <iostream>
#include <string>

struct Unit {
    std::string name;
    int hp = 100;
    int attack = 30;
    int armor = 10;
};

// (1) Read-only query: how much damage would attacker deal to defender?
int ComputeDamage(Unit& attacker, Unit& defender) {
    const int damage = attacker.attack - defender.armor;
    return damage > 0 ? damage : 0;
}

// (2) Must reduce the hp of the caller's unit (never below 0).
void ApplyDamage(Unit target, int amount) {
    target.hp -= amount;
    if (target.hp < 0) target.hp = 0;
}

// (3) The healer may have no ally selected.
//     Returns true only when somebody was actually healed.
bool HealAlly(Unit& ally, int amount) {
    ally.hp += amount;
    return true;
}

// (4) Remembers who a unit is aiming at. The target changes during combat.
class TargetLock {
public:
    explicit TargetLock(Unit& first) : target_(first) {}
    void Retarget(Unit& next) { target_ = next; }
    const Unit& Current() const { return target_; }

private:
    Unit& target_;
};

int main() {
    Unit knight{"Knight", 100, 30, 10};
    Unit orc{"Orc", 80, 25, 5};
    Unit bat{"Bat", 20, 10, 0};

    ApplyDamage(orc, ComputeDamage(knight, orc));
    std::cout << "orc hp: " << orc.hp << " (expected 55)\n";

    // const Unit dummy{"Training Dummy", 1, 0, 0};
    // std::cout << "vs dummy: " << ComputeDamage(knight, dummy) << " (expected 30)\n";

    Unit nobody;  // placeholder passed when no ally is selected
    std::cout << "healed: " << HealAlly(nobody, 10) << " (expected 0)\n";

    TargetLock lock(orc);
    lock.Retarget(bat);
    std::cout << "locked on: " << lock.Current().name << " (expected Bat)\n";
    std::cout << "orc is: " << orc.name << " with hp " << orc.hp << " (expected Orc with hp 55)\n";
    return 0;
}

