#include <cstddef>
#include <string>
#include <vector>

struct Enemy {
    std::string name;
    int id = 0;
    int hp = 0;
};

class EnemyManager {
public:
    // Adds an enemy and returns a reference to it.
    // The reference (like any Enemy* from Find) is only valid until the next
    // Spawn() or Kill(): both may relocate or destroy vector elements.
    Enemy& Spawn(int id, int hp, const std::string& name) {
        enemies_.push_back(Enemy{name, id, hp});
        return enemies_.back();
    }

    // Returns nullptr when no living enemy has this id.
    // Use the result immediately; do not keep it across Spawn()/Kill().
    Enemy* Find(int id) {
        for (Enemy& e : enemies_) {
            if (e.id == id) return &e;
        }
        return nullptr;
    }

    // Removes the enemy from the world. Returns false if it does not exist.
    bool Kill(int id) {
        for (std::size_t i = 0; i < enemies_.size(); ++i) {
            if (enemies_[i].id == id) {
                enemies_.erase(enemies_.begin() + static_cast<std::ptrdiff_t>(i));
                return true;
            }
        }
        return false;
    }

    std::size_t Count() const { return enemies_.size(); }

private:
    std::vector<Enemy> enemies_;
};

// HUD label such as "Orc (120)".
// Fix 1: return by value. The local string is destroyed at the closing brace,
// so a reference to it would dangle. Returning by value moves it (or elides the copy).
std::string MakeLabel(const Enemy& enemy) {
    std::string label = enemy.name + " (" + std::to_string(enemy.hp) + ")";
    return label;
}

// Spawns a boss (500 hp) and then its minions (ids bossId+1, bossId+2, ...).
// The boss is enraged: it gains +50 hp for every minion that joins.
void SpawnBossWave(EnemyManager& mgr, int bossId, int minionCount) {
    mgr.Spawn(bossId, 500, "Boss");
    for (int i = 1; i <= minionCount; ++i) {
        mgr.Spawn(bossId + i, 40, "Minion");
        // Fix 2: never keep a reference across Spawn(). Look the boss up again
        // by id, because push_back may have moved every element.
        if (Enemy* boss = mgr.Find(bossId)) {
            boss->hp += 50;
        }
    }
}

class Turret {
public:
    explicit Turret(EnemyManager& mgr) : mgr_(mgr) {}

    // Starts tracking the enemy. Returns false if it does not exist.
    bool LockOn(int enemyId) {
        targetId_ = enemyId;
        hasTarget_ = mgr_.Find(enemyId) != nullptr;
        return hasTarget_;
    }

    // Deals damage to the locked target.
    // Returns false (and does nothing) when there is no living target.
    bool Fire(int damage) {
        if (!hasTarget_) return false;
        // Fix 3: remember the id, not the address, and resolve it on every shot.
        // A killed or relocated enemy is never reached through a stale pointer.
        Enemy* target = mgr_.Find(targetId_);
        if (target == nullptr) {
            hasTarget_ = false;
            return false;
        }
        target->hp -= damage;
        return true;
    }

private:
    EnemyManager& mgr_;
    int targetId_ = 0;
    bool hasTarget_ = false;
};

