#include <exception>
#include <iostream>
#include <memory>
#include <stdexcept>

// Prints when a resource is acquired and released.
struct Tracer {
    const char* name;
    explicit Tracer(const char* n) : name(n) { std::cout << "acquire " << name << "\n"; }
    ~Tracer() { std::cout << "release " << name << "\n"; }
};

void LoadMesh(bool fileExists) {
    if (!fileExists) throw std::runtime_error("mesh file missing");
}

// Dynamic storage duration + raw owning pointer: nobody releases it on the exception path.
void LoadLevelRaw(bool meshExists) {
    Tracer* texture = new Tracer("raw texture");
    LoadMesh(meshExists);  // throws -> the delete below is skipped
    delete texture;
}

// Automatic objects own everything: stack unwinding destroys them in reverse order.
void LoadLevelRaii(bool meshExists) {
    Tracer audio("audio (automatic)");
    std::unique_ptr<Tracer> texture = std::make_unique<Tracer>("texture (dynamic, owned by unique_ptr)");
    LoadMesh(meshExists);  // throws -> ~unique_ptr, then ~Tracer(audio)
    std::cout << "level ready\n";
}

int main() {
    try {
        LoadLevelRaw(false);
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << " (raw texture was never released)\n";
    }
    try {
        LoadLevelRaii(false);
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    return 0;
}

