#include <cstddef>
#include <memory>
#include <utility>
#include <vector>

enum class EntityType { Goblin, Archer };

// ---- Provided (do not modify: the hidden tests read Entity::alive) ----
class Entity {
public:
    static inline int alive = 0;  // number of Entity objects currently alive

    Entity(int id, int hp) : id_(id), hp_(hp) { ++alive; }
    virtual ~Entity() { --alive; }
    Entity(const Entity&) = delete;
    Entity& operator=(const Entity&) = delete;

    int Id() const { return id_; }
    int Hp() const { return hp_; }
    virtual const char* Name() const = 0;

private:
    int id_;
    int hp_;
};

class Goblin : public Entity {
public:
    explicit Goblin(int id) : Entity(id, 30) {}
    const char* Name() const override { return "Goblin"; }
};

class Archer : public Entity {
public:
    explicit Archer(int id) : Entity(id, 20) {}
    const char* Name() const override { return "Archer"; }
};
// -----------------------------------------------------------------------

// Factory: the return type itself says "the caller now owns this object".
std::unique_ptr<Entity> CreateEntity(EntityType type, int id) {
    switch (type) {
        case EntityType::Goblin: return std::make_unique<Goblin>(id);  // unique_ptr<Goblin> -> unique_ptr<Entity>
        case EntityType::Archer: return std::make_unique<Archer>(id);
    }
    return nullptr;  // unknown enum value
}

class World {
public:
    // Sink parameter: taking unique_ptr by value means the world takes ownership.
    void Add(std::unique_ptr<Entity> entity) {
        if (!entity) return;
        entities_.push_back(std::move(entity));
    }

    // Non-owning observer pointer; valid while the entity stays in the world.
    Entity* Find(int id) const {
        for (const std::unique_ptr<Entity>& e : entities_) {
            if (e->Id() == id) return e.get();
        }
        return nullptr;
    }

    // Moves ownership out to the caller and removes the emptied slot.
    std::unique_ptr<Entity> Extract(int id) {
        for (std::size_t i = 0; i < entities_.size(); ++i) {
            if (entities_[i]->Id() == id) {
                std::unique_ptr<Entity> out = std::move(entities_[i]);
                entities_.erase(entities_.begin() + static_cast<std::ptrdiff_t>(i));
                return out;
            }
        }
        return nullptr;
    }

    std::size_t Count() const { return entities_.size(); }

private:
    std::vector<std::unique_ptr<Entity>> entities_;
};

