#include <algorithm>
#include <cstddef>
#include <utility>

// AI influence map: one float per grid cell (row-major).
// Invariant: cells_ points to exactly Size() floats owned by this object alone.
class InfluenceMap {
public:
    InfluenceMap(int width, int height)
        : width_(width), height_(height), cells_(new float[Size()]) {
        std::fill(cells_, cells_ + Size(), 0.0f);
    }

    // Fix 1: deep copy. Each map gets its own buffer, so two destructors
    // never release the same pointer and edits never leak into the other map.
    InfluenceMap(const InfluenceMap& other)
        : width_(other.width_), height_(other.height_), cells_(new float[other.Size()]) {
        std::copy(other.cells_, other.cells_ + other.Size(), cells_);
    }

    // Fix 2 + 3: copy-and-swap.
    //  - The copy is made first; if new[] throws, *this has not been touched.
    //  - Swap() exchanges width_, height_ and cells_ together, so the
    //    dimensions can never be left behind.
    //  - Self-assignment just swaps with a copy of itself: correct without a special case.
    InfluenceMap& operator=(const InfluenceMap& other) {
        InfluenceMap copy(other);
        Swap(copy);
        return *this;
    }  // `copy` now holds the old buffer and releases it here

    ~InfluenceMap() { delete[] cells_; }

    void Swap(InfluenceMap& other) noexcept {
        std::swap(width_, other.width_);
        std::swap(height_, other.height_);
        std::swap(cells_, other.cells_);
    }

    int Width() const { return width_; }
    int Height() const { return height_; }
    std::size_t Size() const { return static_cast<std::size_t>(width_) * static_cast<std::size_t>(height_); }

    float Get(int x, int y) const { return cells_[Index(x, y)]; }
    void Set(int x, int y, float value) { cells_[Index(x, y)] = value; }

private:
    std::size_t Index(int x, int y) const {
        return static_cast<std::size_t>(y) * static_cast<std::size_t>(width_) + static_cast<std::size_t>(x);
    }

    int width_;
    int height_;
    float* cells_;
};

// Sum of every cell; the AI uses it to compare two snapshots.
// Read-only access: take a const reference instead of copying the whole grid.
float TotalInfluence(const InfluenceMap& map) {
    float total = 0.0f;
    for (int y = 0; y < map.Height(); ++y) {
        for (int x = 0; x < map.Width(); ++x) {
            total += map.Get(x, y);
        }
    }
    return total;
}

