#include <csignal>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <new>
#include <string>
#include <vector>
#include <unistd.h>

#define main __user_main
{{USER_CODE}}
#undef main

// Instrumented array heap. While tracking is on, every new[] block is recorded,
// padded with guard bytes, and on delete[] it is poisoned and kept (never handed
// back to malloc). A second delete[] of the same block, a write past the end, a
// leak, or a read of a released buffer therefore shows up as a counter or as a
// fixed garbage value instead of depending on how the real allocator reacts.
namespace judge_heap {
struct Block {
    unsigned char* p;
    std::size_t n;
    bool live;
};
const int kMaxBlocks = 8192;
const std::size_t kGuard = 256;
Block g_blocks[kMaxBlocks];
int g_blockCount = 0;
bool g_tracking = false;
bool g_failNext = false;
int g_live = 0;
int g_doubleFree = 0;

bool GuardBroken(const Block& b) {
    for (std::size_t i = 0; i < kGuard; ++i) {
        if (b.p[b.n + i] != 0xFD) return true;
    }
    return false;
}
}  // namespace judge_heap

void* operator new[](std::size_t n) {
    using namespace judge_heap;
    if (!g_tracking || g_blockCount >= kMaxBlocks) {
        void* raw = std::malloc(n ? n : 1);
        if (raw == nullptr) throw std::bad_alloc();
        return raw;
    }
    if (g_failNext) {
        g_failNext = false;
        throw std::bad_alloc();
    }
    unsigned char* p = static_cast<unsigned char*>(std::malloc(n + kGuard));
    if (p == nullptr) throw std::bad_alloc();
    std::memset(p, 0xCD, n);
    std::memset(p + n, 0xFD, kGuard);
    g_blocks[g_blockCount].p = p;
    g_blocks[g_blockCount].n = n;
    g_blocks[g_blockCount].live = true;
    ++g_blockCount;
    ++g_live;
    return p;
}

void operator delete[](void* ptr) noexcept {
    using namespace judge_heap;
    if (ptr == nullptr) return;
    for (int i = g_blockCount - 1; i >= 0; --i) {
        if (g_blocks[i].p != ptr) continue;
        if (!g_blocks[i].live) {
            ++g_doubleFree;
            return;
        }
        g_blocks[i].live = false;
        --g_live;
        std::memset(g_blocks[i].p, 0xDD, g_blocks[i].n);
        return;
    }
    std::free(ptr);
}

void operator delete[](void* ptr, std::size_t) noexcept { operator delete[](ptr); }

// Scalar forms: std::vector / std::string allocate through these. They are not
// tracked, but an armed allocation failure applies to them too, so a solution
// that stores its cells in a std::vector is exercised by the same failure case.
void* operator new(std::size_t n) {
    using namespace judge_heap;
    if (g_tracking && g_failNext) {
        g_failNext = false;
        throw std::bad_alloc();
    }
    void* raw = std::malloc(n ? n : 1);
    if (raw == nullptr) throw std::bad_alloc();
    return raw;
}
void operator delete(void* ptr) noexcept { std::free(ptr); }
void operator delete(void* ptr, std::size_t) noexcept { std::free(ptr); }

namespace judge {

const char* const kCases[] = {
    "copy-construct-is-deep",
    "pass-by-value-keeps-original",
    "assign-updates-size-and-cells",
    "self-assign-keeps-data",
    "assign-chain-and-empty-map",
    "alloc-failure-leaves-target-intact",
    "repeated-assign-no-leak",
    "random-vs-reference",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// A crash in learner code must still produce one line per remaining case.
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (유효하지 않은 메모리 접근 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }
std::string Flt(float v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%g", static_cast<double>(v));
    return buf;
}

// Starts tracking for one case and produces the heap verdict at its end.
struct HeapScope {
    int firstBlock;
    int live0;
    HeapScope() : firstBlock(judge_heap::g_blockCount), live0(judge_heap::g_live) {
        judge_heap::g_doubleFree = 0;
        judge_heap::g_failNext = false;
        judge_heap::g_tracking = true;
    }
    ~HeapScope() {
        judge_heap::g_tracking = false;
        judge_heap::g_failNext = false;
    }
    int Live() const { return judge_heap::g_live - live0; }
    std::string End() const {
        using namespace judge_heap;
        if (g_doubleFree != 0) return "같은 버퍼에 delete[]가 " + Num(g_doubleFree) + "회 더 호출됨 (이중 해제: 두 객체가 한 버퍼를 소유)";
        for (int i = firstBlock; i < g_blockCount; ++i) {
            if (GuardBroken(g_blocks[i])) return "할당한 크기(" + Num((long long)(g_blocks[i].n / sizeof(float))) + "칸)를 넘어선 위치에 기록함";
        }
        if (Live() != 0) return "해제되지 않은 버퍼 " + Num(Live()) + "개 (누수)";
        return "";
    }
};

// Reference model: plain dimensions plus a std::vector<float>.
struct Model {
    int w;
    int h;
    std::vector<float> cells;
    Model(int width, int height) : w(width), h(height), cells(static_cast<std::size_t>(width) * static_cast<std::size_t>(height), 0.0f) {}
    float& At(int x, int y) { return cells[static_cast<std::size_t>(y) * static_cast<std::size_t>(w) + static_cast<std::size_t>(x)]; }
};

void Fill(InfluenceMap& map, Model& model, float start) {
    for (int y = 0; y < model.h; ++y) {
        for (int x = 0; x < model.w; ++x) {
            const float v = start + static_cast<float>(y * model.w + x);
            map.Set(x, y, v);
            model.At(x, y) = v;
        }
    }
}

// Compares size first and stops there, so a map with stale dimensions is never indexed.
std::string Diff(const InfluenceMap& map, Model& model, const std::string& who) {
    if (map.Width() != model.w || map.Height() != model.h)
        return who + " 크기 기대 " + Num(model.w) + "x" + Num(model.h) + ", 결과 " + Num(map.Width()) + "x" + Num(map.Height());
    for (int y = 0; y < model.h; ++y) {
        for (int x = 0; x < model.w; ++x) {
            const float got = map.Get(x, y);
            if (!(got == model.At(x, y)))
                return who + " (" + Num(x) + "," + Num(y) + ") 기대 " + Flt(model.At(x, y)) + ", 결과 " + Flt(got);
        }
    }
    return "";
}

std::string CopyConstructDeep() {
    HeapScope heap;
    std::string r = []() -> std::string {
        InfluenceMap a(3, 2);
        Model ma(3, 2);
        Fill(a, ma, 1.0f);
        InfluenceMap b = a;
        Model mb = ma;
        std::string d = Diff(b, mb, "복사본");
        if (!d.empty()) return d;
        b.Set(0, 0, 99.0f);
        mb.At(0, 0) = 99.0f;
        d = Diff(a, ma, "복사본을 수정한 뒤 원본");
        if (!d.empty()) return d + " (얕은 복사: 두 맵이 같은 버퍼를 가리킴)";
        a.Set(2, 1, -5.0f);
        ma.At(2, 1) = -5.0f;
        d = Diff(b, mb, "원본을 수정한 뒤 복사본");
        if (!d.empty()) return d + " (얕은 복사)";
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string PassByValue() {
    HeapScope heap;
    std::string r = []() -> std::string {
        InfluenceMap a(4, 3);
        Model ma(4, 3);
        Fill(a, ma, 1.0f);  // 1 + 2 + ... + 12 = 78
        const float total = TotalInfluence(a);
        if (!(total == 78.0f)) return "TotalInfluence 기대 78, 결과 " + Flt(total);
        std::string d = Diff(a, ma, "TotalInfluence 호출 뒤 원본");
        if (!d.empty()) return d + " (값으로 전달된 사본이 원본의 버퍼를 해제함)";
        if (!(TotalInfluence(a) == 78.0f)) return "두 번째 TotalInfluence 호출 결과가 78이 아님";
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string AssignUpdatesSize() {
    HeapScope heap;
    std::string r = []() -> std::string {
        InfluenceMap small(2, 2);
        Model msmall(2, 2);
        Fill(small, msmall, 10.0f);
        InfluenceMap big(4, 3);
        Model mbig(4, 3);
        Fill(big, mbig, 100.0f);
        InfluenceMap target(2, 2);
        target = big;  // grow
        std::string d = Diff(target, mbig, "2x2 = 4x3 대입 후 대상");
        if (!d.empty()) return d;
        target.Set(3, 2, -1.0f);
        d = Diff(big, mbig, "대입받은 쪽을 수정한 뒤 원본");
        if (!d.empty()) return d + " (얕은 복사)";
        target = small;  // shrink
        d = Diff(target, msmall, "4x3 = 2x2 대입 후 대상");
        if (!d.empty()) return d;
        d = Diff(small, msmall, "대입의 원본");
        if (!d.empty()) return d;
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string SelfAssign() {
    HeapScope heap;
    std::string r = []() -> std::string {
        InfluenceMap a(3, 3);
        Model ma(3, 3);
        Fill(a, ma, 1.0f);
        InfluenceMap& alias = a;
        a = alias;
        std::string d = Diff(a, ma, "자기 대입(a = a) 후");
        if (!d.empty()) return d + " (자기 버퍼를 먼저 해제해 원래 내용을 잃음)";
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string AssignChainAndEmpty() {
    HeapScope heap;
    std::string r = []() -> std::string {
        InfluenceMap a(1, 1), b(2, 1), c(3, 2);
        Model mc(3, 2);
        Fill(c, mc, 7.0f);
        InfluenceMap* returned = &(a = b = c);
        if (returned != &a) return "operator=이 *this의 참조를 반환하지 않음";
        std::string d = Diff(a, mc, "a = b = c 후 a");
        if (!d.empty()) return d;
        d = Diff(b, mc, "a = b = c 후 b");
        if (!d.empty()) return d;
        InfluenceMap empty(0, 0);
        Model mempty(0, 0);
        InfluenceMap emptyCopy = empty;
        d = Diff(emptyCopy, mempty, "0x0 맵의 복사본");
        if (!d.empty()) return d;
        a = empty;
        d = Diff(a, mempty, "0x0 맵을 대입한 뒤");
        if (!d.empty()) return d;
        if (!(TotalInfluence(a) == 0.0f)) return "0x0 맵의 TotalInfluence가 0이 아님";
        a = c;
        d = Diff(a, mc, "0x0 맵에 3x2 맵을 대입한 뒤");
        if (!d.empty()) return d;
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string AllocFailure() {
    HeapScope heap;
    std::string r = []() -> std::string {
        InfluenceMap a(2, 2);
        Model ma(2, 2);
        Fill(a, ma, 1.0f);
        InfluenceMap b(3, 3);
        Model mb(3, 3);
        Fill(b, mb, 50.0f);
        bool threw = false;
        judge_heap::g_failNext = true;  // the next allocation (new[] or new) throws std::bad_alloc
        try {
            a = b;
        } catch (const std::bad_alloc&) {
            threw = true;
        }
        judge_heap::g_failNext = false;
        std::string d = threw ? Diff(a, ma, "할당 실패(bad_alloc) 후 대입 대상")
                              : Diff(a, mb, "대입 후 대상");
        if (!d.empty()) return threw ? d + " (대입은 실패했는데 대상이 이미 바뀜: 강한 예외 보장 위반)" : d;
        d = Diff(b, mb, "대입의 원본");
        if (!d.empty()) return d;
        judge_heap::g_failNext = true;
        try {
            InfluenceMap c(b);
            judge_heap::g_failNext = false;
            d = Diff(c, mb, "복사본");
        } catch (const std::bad_alloc&) {
        }
        judge_heap::g_failNext = false;
        if (!d.empty()) return d;
        a = b;  // a later, successful assignment must still work
        return Diff(a, mb, "할당 실패 이후 다시 대입한 대상");
    }();
    return r.empty() ? heap.End() : r;
}

std::string RepeatedAssignNoLeak() {
    HeapScope heap;
    std::string r = [&heap]() -> std::string {
        InfluenceMap a(8, 8), b(5, 3), c(8, 8);
        Model mb(5, 3), mc(8, 8);
        Fill(b, mb, 1.0f);
        Fill(c, mc, 2.0f);
        for (int i = 0; i < 200; ++i) {
            a = (i % 2 == 0) ? b : c;
        }
        if (heap.Live() > 3) return "맵 3개가 살아 있는데 해제되지 않은 버퍼가 " + Num(heap.Live()) + "개 (대입할 때마다 이전 버퍼가 누수됨)";
        return Diff(a, mc, "200번 대입한 뒤 대상");
    }();
    return r.empty() ? heap.End() : r;
}

std::string RandomVsReference() {
    HeapScope heap;
    std::string r = []() -> std::string {
        InfluenceMap maps[3] = {InfluenceMap(2, 3), InfluenceMap(4, 1), InfluenceMap(0, 0)};
        Model models[3] = {Model(2, 3), Model(4, 1), Model(0, 0)};
        Fill(maps[0], models[0], 1.0f);
        Fill(maps[1], models[1], 20.0f);
        unsigned seed = 20261122u;
        for (int step = 0; step < 300; ++step) {
            seed = seed * 1664525u + 1013904223u;
            const unsigned op = (seed >> 16) % 4;
            seed = seed * 1664525u + 1013904223u;
            const int i = static_cast<int>((seed >> 16) % 3);
            seed = seed * 1664525u + 1013904223u;
            const int j = static_cast<int>((seed >> 16) % 3);
            seed = seed * 1664525u + 1013904223u;
            const unsigned pick = seed >> 16;
            const float value = static_cast<float>(step % 17);
            if (op == 0) {
                if (models[i].w > 0 && models[i].h > 0) {
                    const int x = static_cast<int>(pick % static_cast<unsigned>(models[i].w));
                    const int y = static_cast<int>((pick / 7) % static_cast<unsigned>(models[i].h));
                    maps[i].Set(x, y, value);
                    models[i].At(x, y) = value;
                }
            } else if (op == 1) {
                maps[i] = maps[j];  // i == j is a self-assignment
                models[i] = Model(models[j]);
            } else if (op == 2) {
                InfluenceMap scratch(maps[j]);
                Model mscratch = models[j];
                if (mscratch.w > 0 && mscratch.h > 0) {
                    scratch.Set(0, 0, value + 0.5f);
                    mscratch.At(0, 0) = value + 0.5f;
                }
                maps[i] = scratch;
                models[i] = mscratch;
            } else {
                float expect = 0.0f;
                for (std::size_t k = 0; k < models[i].cells.size(); ++k) expect += models[i].cells[k];
                const float got = TotalInfluence(maps[i]);
                if (!(got == expect)) return "step " + Num(step) + ": TotalInfluence 기대 " + Flt(expect) + ", 결과 " + Flt(got);
            }
            for (int k = 0; k < 3; ++k) {
                std::string d = Diff(maps[k], models[k], "step " + Num(step) + ": 맵 " + Num(k));
                if (!d.empty()) return d;
            }
        }
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    CopyConstructDeep, PassByValue, AssignUpdatesSize, SelfAssign,
    AssignChainAndEmpty, AllocFailure, RepeatedAssignNoLeak, RandomVsReference,
};

}  // namespace judge

int main() {
    using namespace judge;
    const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
    for (int s : signals) std::signal(s, OnCrash);

    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        std::string reason;
        try {
            reason = kFns[i]();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                          : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
        line += "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written; skip static destructors
}

