#include <algorithm>
#include <cstddef>
#include <utility>

// Owning byte buffer for one network packet.
// Invariant: data_ points to exactly size_ bytes owned by this object alone,
// or data_ == nullptr and size_ == 0 (the empty / moved-from state).
class PacketBuffer {
public:
    PacketBuffer() noexcept : data_(nullptr), size_(0) {}

    // Zero-filled buffer of `size` bytes (no allocation when size == 0).
    explicit PacketBuffer(std::size_t size)
        : data_(size ? new unsigned char[size]() : nullptr), size_(size) {}

    ~PacketBuffer() { delete[] data_; }

    // Copy constructor: a new buffer of the same size, then the bytes.
    PacketBuffer(const PacketBuffer& other)
        : data_(other.size_ ? new unsigned char[other.size_] : nullptr), size_(other.size_) {
        std::copy(other.data_, other.data_ + size_, data_);
    }

    // Move constructor: take the pointer, leave the source empty.
    // No allocation, nothing that can throw -> noexcept.
    PacketBuffer(PacketBuffer&& other) noexcept
        : data_(std::exchange(other.data_, nullptr)), size_(std::exchange(other.size_, 0)) {}

    // Copy assignment, written explicitly so that storage is reused when it fits.
    //  - same size: overwrite in place, no allocation, cannot fail
    //  - different size: copy first (may throw, *this untouched), then swap (cannot throw)
    PacketBuffer& operator=(const PacketBuffer& other) {
        if (this == &other) return *this;
        if (size_ == other.size_) {
            std::copy(other.data_, other.data_ + size_, data_);
            return *this;
        }
        PacketBuffer copy(other);
        Swap(copy);
        return *this;
    }  // `copy` holds the old buffer and releases it here

    // Move assignment: move the source into a local first, then swap.
    //  - the source is left empty, and our old buffer is released right here
    //  - self-move (`a = std::move(a)`) ends with the original contents back in *this
    PacketBuffer& operator=(PacketBuffer&& other) noexcept {
        PacketBuffer taken(std::move(other));
        Swap(taken);
        return *this;
    }

    void Swap(PacketBuffer& other) noexcept {
        std::swap(data_, other.data_);
        std::swap(size_, other.size_);
    }

    std::size_t Size() const noexcept { return size_; }
    const unsigned char* Data() const noexcept { return data_; }
    unsigned char& operator[](std::size_t i) { return data_[i]; }
    const unsigned char& operator[](std::size_t i) const { return data_[i]; }

private:
    unsigned char* data_;
    std::size_t size_;
};

tests.template:
#include <csignal>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <new>
#include <string>
#include <type_traits>
#include <utility>
#include <vector>
#include <unistd.h>

#define main __user_main
{{USER_CODE}}
#undef main

// Instrumented heap. While tracking is on, every new[] block is recorded, padded
// with guard bytes, and on delete[] it is poisoned and kept (never handed back to
// malloc). A second delete[] of the same block, a write past the end, a leak, or a
// read of a released buffer therefore shows up as a counter or as a fixed garbage
// value instead of depending on how the real allocator reacts. All bookkeeping
// lives in static storage.
namespace judge_heap {
struct Block {
    unsigned char* p;
    std::size_t n;
    bool live;
};
const int kMaxBlocks = 8192;
const std::size_t kGuard = 256;
Block g_blocks[kMaxBlocks];
int g_blockCount = 0;
bool g_tracking = false;
bool g_failNext = false;
int g_live = 0;
int g_doubleFree = 0;
long g_arrayAllocs = 0;
long g_scalarAllocs = 0;

bool GuardBroken(const Block& b) {
    for (std::size_t i = 0; i < kGuard; ++i) {
        if (b.p[b.n + i] != 0xFD) return true;
    }
    return false;
}
}  // namespace judge_heap

void* operator new[](std::size_t n) {
    using namespace judge_heap;
    if (!g_tracking || g_blockCount >= kMaxBlocks) {
        void* raw = std::malloc(n ? n : 1);
        if (raw == nullptr) throw std::bad_alloc();
        return raw;
    }
    if (g_failNext) {
        g_failNext = false;
        throw std::bad_alloc();
    }
    unsigned char* p = static_cast<unsigned char*>(std::malloc(n + kGuard));
    if (p == nullptr) throw std::bad_alloc();
    std::memset(p, 0xCD, n);
    std::memset(p + n, 0xFD, kGuard);
    g_blocks[g_blockCount].p = p;
    g_blocks[g_blockCount].n = n;
    g_blocks[g_blockCount].live = true;
    ++g_blockCount;
    ++g_live;
    ++g_arrayAllocs;
    return p;
}

void operator delete[](void* ptr) noexcept {
    using namespace judge_heap;
    if (ptr == nullptr) return;
    for (int i = g_blockCount - 1; i >= 0; --i) {
        if (g_blocks[i].p != ptr) continue;
        if (!g_blocks[i].live) {
            ++g_doubleFree;
            return;
        }
        g_blocks[i].live = false;
        --g_live;
        std::memset(g_blocks[i].p, 0xDD, g_blocks[i].n);
        return;
    }
    std::free(ptr);
}

void operator delete[](void* ptr, std::size_t) noexcept { operator delete[](ptr); }

// Scalar forms: std::vector / std::string / make_unique<T> allocate through these.
// They are counted (not tracked), and an armed allocation failure applies to them
// too, so a solution that allocates through them is exercised by the same cases.
void* operator new(std::size_t n) {
    using namespace judge_heap;
    if (g_tracking) {
        if (g_failNext) {
            g_failNext = false;
            throw std::bad_alloc();
        }
        ++g_scalarAllocs;
    }
    void* raw = std::malloc(n ? n : 1);
    if (raw == nullptr) throw std::bad_alloc();
    return raw;
}
void operator delete(void* ptr) noexcept { std::free(ptr); }
void operator delete(void* ptr, std::size_t) noexcept { std::free(ptr); }

namespace judge {

const char* const kCases[] = {
    "copy-is-deep",
    "self-copy-assign-keeps-data",
    "move-construct-steals-buffer",
    "move-assign-transfers-and-frees",
    "self-move-assign-stays-valid",
    "noexcept-moves-in-vector-growth",
    "alloc-failure-leaves-target-intact",
    "random-vs-reference",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// A crash in learner code must still produce one line per remaining case.
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (유효하지 않은 메모리 접근 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }
long Allocs() { return judge_heap::g_arrayAllocs + judge_heap::g_scalarAllocs; }

// Starts tracking for one case and produces the heap verdict at its end.
struct HeapScope {
    int firstBlock;
    int live0;
    HeapScope() : firstBlock(judge_heap::g_blockCount), live0(judge_heap::g_live) {
        judge_heap::g_doubleFree = 0;
        judge_heap::g_failNext = false;
        judge_heap::g_tracking = true;
    }
    ~HeapScope() {
        judge_heap::g_tracking = false;
        judge_heap::g_failNext = false;
    }
    int Live() const { return judge_heap::g_live - live0; }
    std::string End() const {
        using namespace judge_heap;
        if (g_doubleFree != 0) return "같은 버퍼에 delete[]가 " + Num(g_doubleFree) + "회 더 호출됨 (이중 해제: 두 객체가 한 버퍼를 소유)";
        for (int i = firstBlock; i < g_blockCount; ++i) {
            if (GuardBroken(g_blocks[i])) return "할당한 크기(" + Num((long long)g_blocks[i].n) + "바이트)를 넘어선 위치에 기록함";
        }
        if (Live() != 0) return "해제되지 않은 버퍼 " + Num(Live()) + "개 (누수)";
        return "";
    }
};

typedef std::vector<unsigned char> Model;

// Writes the same bytes to both. A buffer whose size is not the expected one is left
// alone (the Diff that follows reports it) so it is never indexed out of range.
void Fill(PacketBuffer& buffer, Model& model, unsigned seed) {
    const bool sizeOk = buffer.Size() == model.size();
    for (std::size_t i = 0; i < model.size(); ++i) {
        const unsigned char v = static_cast<unsigned char>((seed * 31u + static_cast<unsigned>(i) * 7u + 1u) & 0x7Fu);
        if (sizeOk) buffer[i] = v;
        model[i] = v;
    }
}

// Compares size first and stops there, so a buffer with a stale size is never indexed.
std::string Diff(const PacketBuffer& buffer, const Model& model, const std::string& who) {
    if (buffer.Size() != model.size())
        return who + " Size 기대 " + Num((long long)model.size()) + ", 결과 " + Num((long long)buffer.Size());
    for (std::size_t i = 0; i < model.size(); ++i) {
        if (buffer[i] != model[i])
            return who + " [" + Num((long long)i) + "] 기대 " + Num(model[i]) + ", 결과 " + Num(buffer[i]);
    }
    return "";
}

std::string CopyIsDeep() {
    HeapScope heap;
    std::string r = []() -> std::string {
        PacketBuffer a(6);
        Model ma(6);
        Fill(a, ma, 1);
        PacketBuffer b(a);
        Model mb = ma;
        std::string d = Diff(b, mb, "복사 생성한 사본");
        if (!d.empty()) return d;
        if (b.Data() == a.Data()) return "복사본의 Data()가 원본과 같은 주소 (얕은 복사)";
        b[0] = 0xEE;
        mb[0] = 0xEE;
        d = Diff(a, ma, "사본을 수정한 뒤 원본");
        if (!d.empty()) return d + " (얕은 복사)";
        PacketBuffer big(9), small(2);
        Model mbig(9), msmall(2);
        Fill(big, mbig, 2);
        Fill(small, msmall, 3);
        PacketBuffer c(3);
        c = big;  // grow
        d = Diff(c, mbig, "3바이트 = 9바이트 복사 대입 후 대상");
        if (!d.empty()) return d;
        c[8] = 0xEE;
        d = Diff(big, mbig, "대입받은 쪽을 수정한 뒤 원본");
        if (!d.empty()) return d + " (얕은 복사)";
        c = small;  // shrink
        d = Diff(c, msmall, "9바이트 = 2바이트 복사 대입 후 대상");
        if (!d.empty()) return d;
        PacketBuffer x(1), y(4);
        PacketBuffer* returned = &(x = y = a);
        if (returned != &x) return "복사 대입이 *this의 참조를 반환하지 않음";
        d = Diff(x, ma, "x = y = a 후 x");
        if (!d.empty()) return d;
        d = Diff(y, ma, "x = y = a 후 y");
        if (!d.empty()) return d;
        PacketBuffer empty;
        PacketBuffer emptyCopy(empty);
        if (emptyCopy.Size() != 0) return "빈 버퍼의 사본 Size가 0이 아님";
        x = empty;
        if (x.Size() != 0) return "빈 버퍼를 복사 대입한 뒤 Size가 0이 아님";
        x = a;
        return Diff(x, ma, "빈 버퍼에 다시 복사 대입한 뒤");
    }();
    return r.empty() ? heap.End() : r;
}

std::string SelfCopyAssign() {
    HeapScope heap;
    std::string r = []() -> std::string {
        PacketBuffer a(7);
        Model ma(7);
        Fill(a, ma, 4);
        PacketBuffer& alias = a;
        a = alias;
        std::string d = Diff(a, ma, "자기 복사 대입(a = a) 후");
        if (!d.empty()) return d;
        PacketBuffer empty;
        PacketBuffer& emptyAlias = empty;
        empty = emptyAlias;
        if (empty.Size() != 0) return "빈 버퍼의 자기 대입 뒤 Size가 0이 아님";
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string MoveConstructSteals() {
    HeapScope heap;
    std::string r = []() -> std::string {
        PacketBuffer a(32);
        Model ma(32);
        Fill(a, ma, 5);
        const unsigned char* const before = a.Data();
        const long allocs0 = Allocs();
        PacketBuffer b(std::move(a));
        const long allocs1 = Allocs();
        std::string d = Diff(b, ma, "이동 생성한 객체");
        if (!d.empty()) return d;
        if (allocs1 != allocs0) return "이동 생성 중 메모리 할당이 " + Num(allocs1 - allocs0) + "회 일어남 (버퍼를 넘겨받지 않고 복사함)";
        if (b.Data() != before) return "이동 생성한 객체의 Data()가 원본이 갖고 있던 버퍼가 아님";
        if (a.Size() != 0) return "이동된 원본의 Size 기대 0, 결과 " + Num((long long)a.Size()) + " (포인터만 옮기고 크기를 남겨 두면 원본이 유효하지 않음)";
        a = b;  // a moved-from object must accept a new value
        d = Diff(a, ma, "이동된 객체에 다시 복사 대입한 뒤");
        if (!d.empty()) return d;
        PacketBuffer c(std::move(a));  // a is destroyed later in the moved-from state
        d = Diff(c, ma, "두 번째 이동 생성한 객체");
        if (!d.empty()) return d;
        PacketBuffer empty;
        PacketBuffer fromEmpty(std::move(empty));
        if (fromEmpty.Size() != 0 || empty.Size() != 0) return "빈 버퍼를 이동 생성한 결과가 비어 있지 않음";
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string MoveAssignTransfers() {
    HeapScope heap;
    std::string r = []() -> std::string {
        PacketBuffer a(8), b(20);
        Model ma(8), mb(20);
        Fill(a, ma, 6);
        Fill(b, mb, 7);
        const unsigned char* const src = b.Data();
        const long allocs0 = Allocs();
        PacketBuffer* returned = &(a = std::move(b));
        const long allocs1 = Allocs();
        if (returned != &a) return "이동 대입이 *this의 참조를 반환하지 않음";
        std::string d = Diff(a, mb, "이동 대입 후 대상");
        if (!d.empty()) return d;
        if (allocs1 != allocs0) return "이동 대입 중 메모리 할당이 " + Num(allocs1 - allocs0) + "회 일어남 (버퍼를 넘겨받지 않고 복사함)";
        if (a.Data() != src) return "이동 대입 후 대상의 Data()가 원본이 갖고 있던 버퍼가 아님";
        // The source must be valid: either empty or holding the target's old contents.
        if (b.Size() != 0) {
            d = Diff(b, ma, "이동 대입 후 원본");
            if (!d.empty()) return d + " (비어 있지도 않고 대상의 이전 내용도 아님: 유효하지 않은 상태)";
        }
        b = PacketBuffer(5);  // reuse the moved-from object
        Model mb2(5);
        Fill(b, mb2, 8);
        d = Diff(b, mb2, "이동된 객체에 새 버퍼를 이동 대입한 뒤");
        if (!d.empty()) return d;
        PacketBuffer empty;
        empty = std::move(a);
        d = Diff(empty, mb, "빈 버퍼에 이동 대입한 뒤");
        if (!d.empty()) return d;
        PacketBuffer nothing;
        empty = std::move(nothing);
        if (empty.Size() != 0) return "빈 버퍼를 이동 대입한 뒤 대상 Size 기대 0, 결과 " + Num((long long)empty.Size());
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string SelfMoveAssign() {
    HeapScope heap;
    std::string r = []() -> std::string {
        PacketBuffer a(10);
        Model ma(10);
        Fill(a, ma, 9);
        PacketBuffer& alias = a;
        a = std::move(alias);
        // Valid outcomes: the contents are kept, or the buffer is empty.
        if (a.Size() != 0) {
            std::string d = Diff(a, ma, "자기 이동 대입(a = std::move(a)) 후");
            if (!d.empty()) return d + " (해제된 버퍼를 가리키거나 내용이 깨짐)";
        }
        a = PacketBuffer(4);
        Model m2(4);
        Fill(a, m2, 10);
        return Diff(a, m2, "자기 이동 대입 뒤 새 값을 대입한 결과");
    }();
    return r.empty() ? heap.End() : r;
}

std::string NoexceptVectorGrowth() {
    if (!std::is_nothrow_move_constructible<PacketBuffer>::value)
        return "이동 생성자가 noexcept가 아님 (std::vector는 재할당할 때 이동 대신 복사를 고름)";
    if (!std::is_nothrow_move_assignable<PacketBuffer>::value) return "이동 대입 연산자가 noexcept가 아님";
    HeapScope heap;
    std::string r = []() -> std::string {
        std::vector<PacketBuffer> queue;  // no reserve: the vector reallocates several times
        const long arrays0 = judge_heap::g_arrayAllocs;
        for (int i = 0; i < 100; ++i) {
            PacketBuffer packet(16);
            packet[0] = static_cast<unsigned char>(i);
            queue.push_back(std::move(packet));
        }
        const long arrays = judge_heap::g_arrayAllocs - arrays0;
        for (int i = 0; i < 100; ++i) {
            if (queue[static_cast<std::size_t>(i)].Size() != 16 || queue[static_cast<std::size_t>(i)][0] != static_cast<unsigned char>(i))
                return "vector에 넣은 " + Num(i) + "번째 패킷의 내용이 다름";
        }
        if (arrays > 100) return "16바이트 패킷 100개를 push_back하는 동안 new[]가 " + Num(arrays) + "회 호출됨 (기대 100회: 삽입과 재할당에서 원소가 복사됨)";
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

std::string AllocFailure() {
    HeapScope heap;
    std::string r = []() -> std::string {
        PacketBuffer a(4), b(12);
        Model ma(4), mb(12);
        Fill(a, ma, 11);
        Fill(b, mb, 12);
        bool threw = false;
        judge_heap::g_failNext = true;  // the next allocation (new[] or new) throws std::bad_alloc
        try {
            a = b;
        } catch (const std::bad_alloc&) {
            threw = true;
        }
        judge_heap::g_failNext = false;
        std::string d = threw ? Diff(a, ma, "할당 실패(bad_alloc) 후 복사 대입 대상") : Diff(a, mb, "복사 대입 후 대상");
        if (!d.empty()) return threw ? d + " (대입은 실패했는데 대상이 이미 바뀜: 강한 예외 보장 위반)" : d;
        d = Diff(b, mb, "복사 대입의 원본");
        if (!d.empty()) return d;
        judge_heap::g_failNext = true;
        try {
            PacketBuffer c(b);
            judge_heap::g_failNext = false;
            d = Diff(c, mb, "사본");
        } catch (const std::bad_alloc&) {
        }
        judge_heap::g_failNext = false;
        if (!d.empty()) return d;
        a = b;  // a later, successful assignment must still work
        return Diff(a, mb, "할당 실패 이후 다시 복사 대입한 대상");
    }();
    return r.empty() ? heap.End() : r;
}

std::string RandomVsReference() {
    HeapScope heap;
    std::string r = []() -> std::string {
        PacketBuffer bufs[4];
        Model models[4];
        unsigned seed = 20261122u;
        for (int step = 0; step < 400; ++step) {
            seed = seed * 1664525u + 1013904223u;
            const unsigned op = (seed >> 16) % 6;
            seed = seed * 1664525u + 1013904223u;
            const int i = static_cast<int>((seed >> 16) % 4);
            seed = seed * 1664525u + 1013904223u;
            const int j = static_cast<int>((seed >> 16) % 4);
            seed = seed * 1664525u + 1013904223u;
            const unsigned pick = seed >> 16;
            const std::string at = "step " + Num(step) + ": ";
            if (op == 0) {  // write one byte
                if (!models[i].empty()) {
                    const std::size_t k = pick % models[i].size();
                    bufs[i][k] = static_cast<unsigned char>(step & 0x7F);
                    models[i][k] = static_cast<unsigned char>(step & 0x7F);
                }
            } else if (op == 1) {  // fresh buffer of 0..12 bytes
                const std::size_t n = pick % 13;
                bufs[i] = PacketBuffer(n);
                models[i].assign(n, 0);
                Fill(bufs[i], models[i], pick);
            } else if (op == 2) {  // copy assignment (i == j is a self-assignment)
                bufs[i] = bufs[j];
                models[i] = Model(models[j]);
            } else if (op == 3) {  // move assignment
                const Model oldTarget = models[i];
                const Model oldSource = models[j];
                bufs[i] = std::move(bufs[j]);
                if (i == j) {
                    if (bufs[i].Size() == 0) models[i].clear();
                } else {
                    models[i] = oldSource;
                    if (bufs[j].Size() == 0) {
                        models[j].clear();
                    } else {
                        models[j] = oldTarget;
                    }
                }
            } else if (op == 4) {  // copy construct, edit the copy, move it in
                PacketBuffer scratch(bufs[j]);
                Model mscratch = models[j];
                if (!mscratch.empty()) {
                    scratch[0] = 0x55;
                    mscratch[0] = 0x55;
                }
                bufs[i] = std::move(scratch);
                models[i] = mscratch;
            } else {  // move construct out of j, then copy the result into i
                PacketBuffer taken(std::move(bufs[j]));
                const Model mtaken = models[j];
                if (bufs[j].Size() != 0) return at + "이동 생성의 원본 Size 기대 0, 결과 " + Num((long long)bufs[j].Size());
                models[j].clear();
                bufs[i] = taken;
                models[i] = mtaken;
            }
            for (int k = 0; k < 4; ++k) {
                std::string d = Diff(bufs[k], models[k], at + "버퍼 " + Num(k));
                if (!d.empty()) return d;
            }
        }
        return "";
    }();
    return r.empty() ? heap.End() : r;
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    CopyIsDeep, SelfCopyAssign, MoveConstructSteals, MoveAssignTransfers,
    SelfMoveAssign, NoexceptVectorGrowth, AllocFailure, RandomVsReference,
};

}  // namespace judge

int main() {
    using namespace judge;
    const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
    for (int s : signals) std::signal(s, OnCrash);

    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        std::string reason;
        try {
            reason = kFns[i]();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                          : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
        line += "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written; skip static destructors
}

