#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <memory>
#include <new>

// Counts heap allocations so the claims below are measured, not assumed.
static int g_allocations = 0;
void* operator new(std::size_t n) {
    ++g_allocations;
    void* p = std::malloc(n ? n : 1);
    if (p == nullptr) throw std::bad_alloc();
    return p;
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct Texture {
    int id = 0;
    char pixels[256] = {};
};

// An object that hands out shared ownership of itself.
struct Enemy : std::enable_shared_from_this<Enemy> {
    std::shared_ptr<Enemy> Self() { return shared_from_this(); }
};

// Registers itself from inside its own constructor: too early, no shared_ptr owns it yet.
struct EagerEnemy : std::enable_shared_from_this<EagerEnemy> {
    bool registered = false;
    EagerEnemy() {
        try {
            std::shared_ptr<EagerEnemy> self = shared_from_this();
            registered = true;
        } catch (const std::bad_weak_ptr&) {
            registered = false;
        }
    }
};

int main() {
    // 1. Size of the handles (implementation-specific: print, do not memorize).
    auto closeFile = [](std::FILE* f) { if (f != nullptr) std::fclose(f); };
    std::cout << "sizeof(Texture*)                       = " << sizeof(Texture*) << "\n";
    std::cout << "sizeof(unique_ptr<Texture>)            = " << sizeof(std::unique_ptr<Texture>) << "\n";
    std::cout << "sizeof(unique_ptr<FILE, lambda>)       = " << sizeof(std::unique_ptr<std::FILE, decltype(closeFile)>) << "\n";
    std::cout << "sizeof(unique_ptr<FILE, int(*)(FILE*)>) = " << sizeof(std::unique_ptr<std::FILE, int (*)(std::FILE*)>) << "\n";
    std::cout << "sizeof(shared_ptr<Texture>)            = " << sizeof(std::shared_ptr<Texture>) << "\n";
    std::cout << "sizeof(weak_ptr<Texture>)              = " << sizeof(std::weak_ptr<Texture>) << "\n";

    // 2. Allocations: object + control block separately, or both in one block.
    int before = g_allocations;
    std::shared_ptr<Texture> viaNew(new Texture);
    std::cout << "shared_ptr<Texture>(new Texture): " << (g_allocations - before) << " allocation(s)\n";
    before = g_allocations;
    std::shared_ptr<Texture> viaMake = std::make_shared<Texture>();
    std::cout << "make_shared<Texture>():           " << (g_allocations - before) << " allocation(s)\n";
    before = g_allocations;
    std::unique_ptr<Texture> unique = std::make_unique<Texture>();
    std::cout << "make_unique<Texture>():           " << (g_allocations - before) << " allocation(s)\n";

    // 3. Copying a shared_ptr changes the shared count; a weak_ptr does not own.
    std::shared_ptr<Texture> copy = viaMake;
    std::weak_ptr<Texture> observer = viaMake;
    std::cout << "use_count with 2 owners + 1 weak: " << viaMake.use_count() << "\n";
    copy.reset();
    viaMake.reset();
    std::cout << "expired after the last owner left: " << observer.expired() << "\n";
    std::cout << "lock() on an expired weak_ptr is null: " << (observer.lock() == nullptr) << "\n";

    // 4. enable_shared_from_this: only valid for objects already owned by a shared_ptr.
    std::shared_ptr<Enemy> enemy = std::make_shared<Enemy>();
    std::shared_ptr<Enemy> again = enemy->Self();
    std::cout << "use_count after shared_from_this: " << enemy.use_count() << "\n";
    Enemy onStack;
    try {
        onStack.Self();
    } catch (const std::bad_weak_ptr&) {
        std::cout << "shared_from_this on an unowned object: std::bad_weak_ptr\n";
    }
    std::shared_ptr<EagerEnemy> eager = std::make_shared<EagerEnemy>();
    std::cout << "shared_from_this inside the constructor worked: " << eager->registered << "\n";
    return 0;
}

