#include <algorithm>
#include <cstddef>
#include <string>
#include <unordered_map>
#include <vector>

struct Enemy {
    int id = 0;
    int hp = 0;
    int splits = 0;  // how many more times this slime splits when it dies
    std::string name;
};

// A dead enemy that can still split spawns two smaller slimes at the end of the
// turn order. Each child gets the next free id, 15 hp per split the parent had
// left, and one split fewer than its parent.
void SplitDeadSlimes(std::vector<Enemy>& enemies, int& nextId) {
    // Fix 1: push_back may reallocate, which invalidates every iterator and
    // reference into the vector (including the hidden iterators of a range-for).
    // Walk by index over the enemies that existed when the function was called,
    // and copy what is needed from the parent BEFORE the first push_back.
    const std::size_t parentCount = enemies.size();
    for (std::size_t i = 0; i < parentCount; ++i) {
        if (enemies[i].hp > 0 || enemies[i].splits <= 0) continue;
        const int splits = enemies[i].splits;
        for (int child = 0; child < 2; ++child) {
            enemies.push_back(Enemy{nextId++, 15 * splits, splits - 1, "Slimeling"});
        }
    }
}

// Removes every enemy with hp <= 0 and keeps the turn order of the survivors.
// Returns how many enemies were removed.
int RemoveDead(std::vector<Enemy>& enemies) {
    // Fix 2: erase-remove idiom. remove_if moves the survivors to the front in
    // their original order (one pass, O(n)); a single erase then cuts off the tail.
    // No iterator is used after the call that invalidates it.
    const auto firstDead = std::remove_if(enemies.begin(), enemies.end(),
                                          [](const Enemy& e) { return e.hp <= 0; });
    const int removed = static_cast<int>(enemies.end() - firstDead);
    enemies.erase(firstDead, enemies.end());
    return removed;
}

// Summoned minions are stored by id. Removes the dead ones and returns how many.
int RemoveDeadMinions(std::unordered_map<int, Enemy>& minions) {
    // Fix 3: erase(iterator) invalidates only the erased element and returns the
    // iterator that follows it. Advance with that return value, or with ++it,
    // never both.
    int removed = 0;
    for (auto it = minions.begin(); it != minions.end();) {
        if (it->second.hp <= 0) {
            it = minions.erase(it);
            ++removed;
        } else {
            ++it;
        }
    }
    return removed;
}

