// Checked standard library. With _GLIBCXX_DEBUG, libstdc++'s std::vector and
// std::unordered_map hand out "safe iterators" that know when the container has
// invalidated them. Incrementing, dereferencing or comparing an invalidated iterator
// is reported on stderr and the program is aborted (SIGABRT) at that exact point,
// instead of silently reading whatever happens to be in memory. Correct code is not
// affected. https://gcc.gnu.org/onlinedocs/libstdc++/manual/debug_mode.html
#define _GLIBCXX_DEBUG 1
#include <cerrno>
#include <csignal>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <map>
#include <new>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>
#include <sys/resource.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

// Quarantining heap, for the one misuse the checked library cannot see: a plain
// reference or pointer to an element that is read after the vector reallocated.
// Memory released by operator delete is overwritten with a fixed pattern (0xDD) and
// never handed back to the allocator, so such a read returns the same wrong value on
// every run and a stale write cannot reach another object. The size of each block is
// kept in a 16-byte header.
namespace judge_heap {
const std::size_t kHeader = 16;
}
void* operator new(std::size_t n) {
    unsigned char* raw = static_cast<unsigned char*>(std::malloc(n + judge_heap::kHeader));
    if (raw == nullptr) throw std::bad_alloc();
    std::memcpy(raw, &n, sizeof(n));
    return raw + judge_heap::kHeader;
}
void* operator new[](std::size_t n) { return operator new(n); }
void operator delete(void* p) noexcept {
    if (p == nullptr) return;
    std::size_t n = 0;
    std::memcpy(&n, static_cast<unsigned char*>(p) - judge_heap::kHeader, sizeof(n));
    std::memset(p, 0xDD, n);
}
void operator delete[](void* p) noexcept { operator delete(p); }
void operator delete(void* p, std::size_t) noexcept { operator delete(p); }
void operator delete[](void* p, std::size_t) noexcept { operator delete(p); }

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "vector-nothing-to-remove",
    "vector-adjacent-dead",
    "split-appends-two-children",
    "split-many-parents-in-order",
    "vector-tail-and-all-dead",
    "map-removes-only-dead",
    "map-all-dead-and-empty",
    "random-vs-reference",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// Only used when the judge cannot run a case in its own process (see main).
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (무효화된 반복자/참조 사용 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }

Enemy Make(int id, int hp, int splits, const char* name) {
    Enemy e;
    e.id = id;
    e.hp = hp;
    e.splits = splits;
    e.name = name;
    return e;
}

// A vector whose capacity equals its size, so the next push_back must reallocate.
std::vector<Enemy> Tight(const std::vector<Enemy>& src) {
    std::vector<Enemy> v;
    v.reserve(src.size());
    for (const Enemy& e : src) v.push_back(e);
    return v;
}

std::string DiffEnemy(const Enemy& got, const Enemy& want, const std::string& who) {
    if (got.id != want.id) return who + " id 기대 " + Num(want.id) + ", 결과 " + Num(got.id);
    if (got.hp != want.hp) return who + "(id " + Num(want.id) + ") hp 기대 " + Num(want.hp) + ", 결과 " + Num(got.hp);
    if (got.splits != want.splits) return who + "(id " + Num(want.id) + ") splits 기대 " + Num(want.splits) + ", 결과 " + Num(got.splits);
    if (got.name.size() != want.name.size() || got.name != want.name) return who + "(id " + Num(want.id) + ") 이름이 기대(" + want.name + ")와 다름";
    return "";
}

std::string DiffVec(const std::vector<Enemy>& got, const std::vector<Enemy>& want, const std::string& who) {
    if (got.size() != want.size()) return who + " 적 수 기대 " + Num((long long)want.size()) + ", 결과 " + Num((long long)got.size());
    for (std::size_t i = 0; i < want.size(); ++i) {
        std::string d = DiffEnemy(got[i], want[i], who + " [" + Num((long long)i) + "]");
        if (!d.empty()) return d;
    }
    return "";
}

// Reference implementations: build a fresh container, never erase in place.
std::vector<Enemy> AliveOf(const std::vector<Enemy>& src) {
    std::vector<Enemy> out;
    for (const Enemy& e : src) {
        if (e.hp > 0) out.push_back(e);
    }
    return out;
}

std::vector<Enemy> SplitOf(const std::vector<Enemy>& src, int& nextId) {
    std::vector<Enemy> out = src;
    for (const Enemy& e : src) {
        if (e.hp <= 0 && e.splits > 0) {
            out.push_back(Make(nextId++, 15 * e.splits, e.splits - 1, "Slimeling"));
            out.push_back(Make(nextId++, 15 * e.splits, e.splits - 1, "Slimeling"));
        }
    }
    return out;
}

std::string CheckRemove(const std::vector<Enemy>& input, const std::string& who) {
    std::vector<Enemy> v = Tight(input);
    const std::vector<Enemy> want = AliveOf(input);
    const int removed = RemoveDead(v);
    const int wantRemoved = static_cast<int>(input.size() - want.size());
    std::string d = DiffVec(v, want, who);
    if (!d.empty()) return d;
    if (removed != wantRemoved) return who + " 반환값(제거한 수) 기대 " + Num(wantRemoved) + ", 결과 " + Num(removed);
    return "";
}

std::string CheckSplit(const std::vector<Enemy>& input, bool tight, int firstId, const std::string& who) {
    std::vector<Enemy> v;
    if (tight) {
        v = Tight(input);
    } else {
        v.reserve(input.size() * 3 + 8);
        for (const Enemy& e : input) v.push_back(e);
    }
    int wantId = firstId;
    const std::vector<Enemy> want = SplitOf(input, wantId);
    int nextId = firstId;
    SplitDeadSlimes(v, nextId);
    std::string d = DiffVec(v, want, who);
    if (!d.empty()) return d;
    if (nextId != wantId) return who + " nextId 기대 " + Num(wantId) + ", 결과 " + Num(nextId);
    return "";
}

std::string CheckMinions(const std::vector<Enemy>& input, const std::string& who) {
    std::unordered_map<int, Enemy> minions;
    std::map<int, Enemy> want;
    int wantRemoved = 0;
    for (const Enemy& e : input) {
        minions[e.id] = e;
        if (e.hp > 0) {
            want[e.id] = e;
        } else {
            ++wantRemoved;
        }
    }
    const int removed = RemoveDeadMinions(minions);
    if (minions.size() != want.size()) return who + " 남은 미니언 수 기대 " + Num((long long)want.size()) + ", 결과 " + Num((long long)minions.size());
    for (const auto& kv : want) {
        const auto found = minions.find(kv.first);
        if (found == minions.end()) return who + " 살아 있는 미니언 id " + Num(kv.first) + "이(가) 사라짐";
        std::string d = DiffEnemy(found->second, kv.second, who + " 미니언");
        if (!d.empty()) return d;
    }
    if (removed != wantRemoved) return who + " 반환값(제거한 수) 기대 " + Num(wantRemoved) + ", 결과 " + Num(removed);
    return "";
}

std::string VectorNothingToRemove() {
    std::string d = CheckRemove({}, "빈 목록:");
    if (!d.empty()) return d;
    return CheckRemove({Make(1, 30, 0, "Orc"), Make(2, 1, 0, "Bat"), Make(3, 12, 1, "Slime")}, "모두 생존:");
}

std::string VectorAdjacentDead() {
    // Two and three dead enemies in a row; the last two enemies are alive.
    return CheckRemove({Make(1, 30, 0, "Orc"), Make(2, 0, 0, "Bat"), Make(3, -5, 0, "Imp"), Make(4, 9, 0, "Wolf"),
                        Make(5, 0, 0, "Rat"), Make(6, 0, 0, "Bug"), Make(7, -1, 0, "Eel"), Make(8, 44, 0, "Ogre"),
                        Make(9, 3, 0, "Crow")},
                       "연속으로 죽은 적:");
}

std::string SplitAppendsTwo() {
    std::string d = CheckSplit({Make(1, 20, 0, "Orc"), Make(2, 0, 2, "Slime"), Make(3, 8, 1, "Slime")}, true, 100, "분열 1마리(용량 = 크기):");
    if (!d.empty()) return d + " (push_back이 재할당하면 순회 중이던 참조가 무효화됨)";
    return CheckSplit({}, true, 5, "빈 목록:");
}

std::string SplitManyParents() {
    const std::vector<Enemy> input = {Make(1, 0, 1, "Slime"),  Make(2, 0, 0, "Bat"),   Make(3, 7, 3, "Slime"),
                                      Make(4, -2, 3, "Slime"), Make(5, 0, 2, "Slime"), Make(6, 15, 0, "Orc")};
    std::string d = CheckSplit(input, true, 50, "분열 3마리(용량 = 크기):");
    if (!d.empty()) return d;
    return CheckSplit(input, false, 50, "분열 3마리(용량 여유):");
}

std::string VectorTailAndAllDead() {
    std::string d = CheckRemove({Make(1, 30, 0, "Orc"), Make(2, 5, 0, "Bat"), Make(3, 0, 0, "Imp")}, "마지막 적이 죽음:");
    if (!d.empty()) return d;
    d = CheckRemove({Make(1, 0, 0, "Orc")}, "한 마리뿐인 적이 죽음:");
    if (!d.empty()) return d;
    return CheckRemove({Make(1, 0, 0, "Orc"), Make(2, -3, 0, "Bat"), Make(3, 0, 0, "Imp"), Make(4, 0, 0, "Rat")}, "전멸:");
}

std::string MapRemovesOnlyDead() {
    std::vector<Enemy> input;
    for (int id = 1; id <= 40; ++id) input.push_back(Make(id, (id % 3 == 0) ? 0 : id, 0, "Minion"));
    std::string d = CheckMinions(input, "미니언 40마리 중 13마리 사망:");
    if (!d.empty()) return d;
    return CheckMinions({Make(7, 10, 0, "Imp"), Make(8, 20, 0, "Imp")}, "모두 생존:");
}

std::string MapAllDeadAndEmpty() {
    std::string d = CheckMinions({}, "빈 맵:");
    if (!d.empty()) return d;
    d = CheckMinions({Make(1, 0, 0, "Imp")}, "한 마리뿐인 미니언이 죽음:");
    if (!d.empty()) return d;
    std::vector<Enemy> input;
    for (int id = 1; id <= 25; ++id) input.push_back(Make(id * 11, -id, 0, "Minion"));
    return CheckMinions(input, "전멸:");
}

std::string RandomVsReference() {
    unsigned seed = 20261122u;
    for (int round = 0; round < 60; ++round) {
        std::vector<Enemy> input;
        seed = seed * 1664525u + 1013904223u;
        const int n = static_cast<int>((seed >> 16) % 14);
        for (int i = 0; i < n; ++i) {
            seed = seed * 1664525u + 1013904223u;
            const int hp = ((seed >> 16) % 5 < 2) ? 0 : static_cast<int>((seed >> 20) % 50) + 1;
            seed = seed * 1664525u + 1013904223u;
            const int splits = static_cast<int>((seed >> 16) % 3);
            input.push_back(Make(i + 1, hp, splits, splits > 0 ? "Slime" : "Grunt"));
        }
        const std::string who = "round " + Num(round) + ": ";
        std::string d = CheckSplit(input, round % 2 == 0, 1000, who + "분열");
        if (!d.empty()) return d;
        // The real end-of-turn order: split first, then remove the dead.
        int id = 1000;
        const std::vector<Enemy> afterSplit = SplitOf(input, id);
        d = CheckRemove(afterSplit, who + "분열 후 정리");
        if (!d.empty()) return d;
        d = CheckMinions(input, who + "미니언");
        if (!d.empty()) return d;
    }
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    VectorNothingToRemove, VectorAdjacentDead, SplitAppendsTwo, SplitManyParents,
    VectorTailAndAllDead,  MapRemovesOnlyDead, MapAllDeadAndEmpty, RandomVsReference,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                      : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 1;  // a correct case finishes in milliseconds
const int kMaxTimeouts = 3;       // after this many, the remaining cases are not started

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT) return "표준 라이브러리 검사 모드가 잘못된 컨테이너 사용을 감지해 중단함(SIGABRT): 무효화된 반복자를 증가·역참조·비교했을 가능성 (erase/push_back 뒤에 그 전에 얻은 반복자를 쓰지 않는지 확인)";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음 (반복자를 전진시키지 않는 무한 루프 가능성)";
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료 (무효화된 참조·포인터 사용 가능성)";
        if (sig == SIGKILL) return "실행 환경이 프로세스를 강제 종료함 (메모리 한도 초과 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Checked-library reports are word-wrapped at about 78 columns by default. In
    // libstdc++ 13 a single word of exactly 77 columns (a long type name, for example)
    // makes that wrapping print blank lines until the process is killed (reproduced on
    // this judge). A large GLIBCXX_DEBUG_MESSAGE_LENGTH, a variable the libstdc++ manual
    // documents, turns the wrapping off in practice.
    setenv("GLIBCXX_DEBUG_MESSAGE_LENGTH", "100000", 1);
    // Every case runs in its own child process. An abort, a crash or an endless loop
    // therefore costs only that case: the other cases still run and report their own
    // results.
    int timeouts = 0;
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        if (timeouts >= kMaxTimeouts) {
            const std::string skipped = std::string("[FAIL] ") + kCases[i] + " :: 앞선 케이스 " + Num(timeouts) +
                                        "개가 시간 초과되어 이 케이스는 실행하지 않음 (끝나지 않는 루프를 먼저 고치세요)\n";
            Emit(skipped.c_str());
            continue;
        }
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            // A container that grows without bound must end in std::bad_alloc instead of
            // the sandbox killing the process.
            struct rlimit memory;
            memory.rlim_cur = memory.rlim_max = static_cast<rlim_t>(256) * 1024 * 1024;
            setrlimit(RLIMIT_AS, &memory);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            // No process isolation available: run in this process. A crash then ends the
            // run, and OnCrash still writes one line for every remaining case.
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        if (waited == pid && WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) ++timeouts;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written
}

