#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <memory>
#include <typeindex>
#include <typeinfo>
#include <unordered_map>
#include <utility>
#include <vector>

namespace detail {

// Handlers of one event type. The virtual base lets the bus keep lists of
// different event types in one map; the typed part never needs a cast to void*.
struct HandlerListBase {
    virtual ~HandlerListBase() = default;
    // Ends the subscription `id`. While a Publish is running the slot is only
    // marked inactive: its handler might be the one executing right now.
    virtual void Remove(std::uint64_t id, bool deferred) noexcept = 0;
    // Destroys the handlers of slots marked inactive. Only called when no
    // Publish is running.
    virtual void Compact() noexcept = 0;
};

template <class E>
struct HandlerList final : HandlerListBase {
    struct Slot {
        std::uint64_t id = 0;
        bool active = true;
        std::function<void(const E&)> handler;
    };
    // unique_ptr keeps every Slot at a fixed address, so a handler that subscribes
    // during a Publish (and makes this vector grow) is not moved while it runs.
    std::vector<std::unique_ptr<Slot>> slots;

    void Remove(std::uint64_t id, bool deferred) noexcept override {
        for (std::size_t i = 0; i < slots.size(); ++i) {
            if (slots[i]->id != id) continue;
            if (deferred) {
                slots[i]->active = false;
            } else {
                slots.erase(slots.begin() + static_cast<std::ptrdiff_t>(i));  // destroys the handler now
            }
            return;
        }
    }

    void Compact() noexcept override {
        slots.erase(std::remove_if(slots.begin(), slots.end(),
                                   [](const std::unique_ptr<Slot>& s) { return !s->active; }),
                    slots.end());
    }
};

// Everything the bus owns. Subscriptions see it only through std::weak_ptr, so a
// handle that outlives the bus finds out that the bus is gone instead of
// touching a destroyed object.
struct BusState {
    std::unordered_map<std::type_index, std::unique_ptr<HandlerListBase>> lists;
    std::uint64_t nextId = 1;
    int publishDepth = 0;   // > 0 while any Publish (possibly nested) is running
    bool dirty = false;     // some slot was marked inactive during a Publish

    void Remove(std::type_index type, std::uint64_t id) noexcept {
        const auto it = lists.find(type);
        if (it == lists.end()) return;
        const bool deferred = publishDepth > 0;
        it->second->Remove(id, deferred);
        if (deferred) dirty = true;
    }

    void CompactAll() noexcept {
        for (auto& entry : lists) entry.second->Compact();
        dirty = false;
    }
};

}  // namespace detail

class EventBus;

// Move-only handle returned by EventBus::Subscribe. While it is active, its
// handler receives events; destroying or resetting it unsubscribes.
class Subscription {
public:
    Subscription() noexcept = default;  // empty: subscribed to nothing
    ~Subscription() { Reset(); }

    Subscription(Subscription&& other) noexcept
        : state_(std::move(other.state_)), type_(other.type_), id_(std::exchange(other.id_, 0)) {}

    Subscription& operator=(Subscription&& other) noexcept {
        if (this != &other) {
            Reset();  // the handler this handle owned until now
            state_ = std::move(other.state_);
            type_ = other.type_;
            id_ = std::exchange(other.id_, 0);
        }
        return *this;
    }

    Subscription(const Subscription&) = delete;
    Subscription& operator=(const Subscription&) = delete;

    // Unsubscribes now. Safe to call more than once, after a move, and after the
    // bus has been destroyed.
    void Reset() noexcept {
        if (id_ == 0) return;
        if (const std::shared_ptr<detail::BusState> state = state_.lock()) state->Remove(type_, id_);
        state_.reset();
        id_ = 0;
    }

    // True while the handler is registered with a bus that still exists.
    bool Active() const noexcept { return id_ != 0 && !state_.expired(); }

private:
    friend class EventBus;
    Subscription(std::weak_ptr<detail::BusState> state, std::type_index type, std::uint64_t id) noexcept
        : state_(std::move(state)), type_(type), id_(id) {}

    std::weak_ptr<detail::BusState> state_;
    std::type_index type_ = typeid(void);
    std::uint64_t id_ = 0;  // 0 = empty handle
};

// Type-safe publish/subscribe for gameplay events (DamageEvent, DeathEvent, ...).
class EventBus {
public:
    EventBus() : state_(std::make_shared<detail::BusState>()) {}
    // Destroying state_ destroys every handler; outstanding Subscriptions then see
    // an expired weak_ptr.
    ~EventBus() = default;

    EventBus(const EventBus&) = delete;
    EventBus& operator=(const EventBus&) = delete;

    // Registers a handler for events of exactly type E.
    template <class E>
    [[nodiscard]] Subscription Subscribe(std::function<void(const E&)> handler) {
        detail::HandlerList<E>& list = ListFor<E>();
        auto slot = std::make_unique<typename detail::HandlerList<E>::Slot>();
        slot->id = state_->nextId++;
        slot->handler = std::move(handler);
        const std::uint64_t id = slot->id;
        list.slots.push_back(std::move(slot));
        return Subscription(state_, std::type_index(typeid(E)), id);
    }

    // Calls every active handler of E in subscription order. Handlers subscribed
    // during this call are first called by the next Publish.
    template <class E>
    void Publish(const E& event) {
        const auto it = state_->lists.find(std::type_index(typeid(E)));
        if (it == state_->lists.end()) return;
        // A reference to the mapped value stays valid even if a handler subscribes
        // to a new event type and the map rehashes; the iterator would not.
        auto& list = static_cast<detail::HandlerList<E>&>(*it->second);
        DepthGuard guard(*state_);
        const std::size_t count = list.slots.size();  // only handlers that existed at the start
        for (std::size_t i = 0; i < count; ++i) {
            auto* slot = list.slots[i].get();  // re-read: the vector may have grown
            if (slot->active) slot->handler(event);
        }
    }

    // Number of active handlers for E.
    template <class E>
    std::size_t HandlerCount() const {
        const auto it = state_->lists.find(std::type_index(typeid(E)));
        if (it == state_->lists.end()) return 0;
        const auto& list = static_cast<const detail::HandlerList<E>&>(*it->second);
        return static_cast<std::size_t>(std::count_if(
            list.slots.begin(), list.slots.end(),
            [](const auto& s) { return s->active; }));
    }

private:
    // Counts nested Publish calls; when the outermost one ends (normally or by an
    // exception from a handler), the slots ended meanwhile are destroyed.
    struct DepthGuard {
        detail::BusState& state;
        explicit DepthGuard(detail::BusState& s) noexcept : state(s) { ++state.publishDepth; }
        ~DepthGuard() {
            if (--state.publishDepth == 0 && state.dirty) state.CompactAll();
        }
        DepthGuard(const DepthGuard&) = delete;
        DepthGuard& operator=(const DepthGuard&) = delete;
    };

    template <class E>
    detail::HandlerList<E>& ListFor() {
        std::unique_ptr<detail::HandlerListBase>& entry = state_->lists[std::type_index(typeid(E))];
        if (!entry) entry = std::make_unique<detail::HandlerList<E>>();
        return static_cast<detail::HandlerList<E>&>(*entry);
    }

    std::shared_ptr<detail::BusState> state_;
};

