// Checked standard library. With _GLIBCXX_DEBUG, libstdc++'s containers report an
// invalidated iterator or an out-of-range operator[] on stderr and abort (SIGABRT)
// at that exact point. Correct code is not affected.
// https://gcc.gnu.org/onlinedocs/libstdc++/manual/debug_mode.html
#define _GLIBCXX_DEBUG 1
#include <cerrno>
#include <csignal>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <functional>
#include <new>
#include <string>
#include <type_traits>
#include <utility>
#include <vector>
#include <sys/resource.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

// Quarantining heap: memory released by operator delete is overwritten with 0xDD
// and never handed out again, so code that keeps using a destroyed bus or a moved
// handler reads the same poison on every run instead of whatever happens to be there.
namespace judge_heap {
const std::size_t kHeader = 16;
}
void* operator new(std::size_t n) {
    unsigned char* raw = static_cast<unsigned char*>(std::malloc(n + judge_heap::kHeader));
    if (raw == nullptr) throw std::bad_alloc();
    std::memcpy(raw, &n, sizeof(n));
    return raw + judge_heap::kHeader;
}
void* operator new[](std::size_t n) { return operator new(n); }
void operator delete(void* p) noexcept {
    if (p == nullptr) return;
    std::size_t n = 0;
    std::memcpy(&n, static_cast<unsigned char*>(p) - judge_heap::kHeader, sizeof(n));
    std::memset(p, 0xDD, n);
}
void operator delete[](void* p) noexcept { operator delete(p); }
void operator delete(void* p, std::size_t) noexcept { operator delete(p); }
void operator delete[](void* p, std::size_t) noexcept { operator delete(p); }

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "publish-matches-type-and-order",
    "reset-and-destructor-unsubscribe",
    "move-transfers-subscription",
    "bus-destroyed-first",
    "unsubscribe-during-publish",
    "subscribe-during-publish",
    "nested-publish",
    "random-vs-reference",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

std::string Num(long long v) { return std::to_string(v); }

struct DamageEvent { int target; int amount; };
struct HealEvent { int target; int amount; };
struct DeathEvent { int unit; };
struct LootEvent { int item; };
struct QuestEvent { int quest; };
int ValueOf(const DamageEvent& e) { return e.amount; }
int ValueOf(const HealEvent& e) { return e.amount; }
int ValueOf(const DeathEvent& e) { return e.unit; }
int ValueOf(const LootEvent& e) { return e.item; }
int ValueOf(const QuestEvent& e) { return e.quest; }

// Every handler call is logged as (tag, value read from the event).
struct Call { int tag; int value; };
std::vector<Call> g_log;

// Instrumented handler. Construction and destruction are counted, and a Probe that
// is destroyed while its own operator() is still running is counted separately:
// that is the observable form of "the bus destroyed a handler while it ran".
int g_alive = 0;
int g_destroyedWhileRunning = 0;
const void* g_running[32];
int g_runningDepth = 0;
typedef void (*Action)(int tag);

struct Probe {
    int tag;
    Action action;
    explicit Probe(int t, Action a = nullptr) : tag(t), action(a) { ++g_alive; }
    Probe(const Probe& o) : tag(o.tag), action(o.action) { ++g_alive; }
    Probe(Probe&& o) noexcept : tag(o.tag), action(o.action) { ++g_alive; }
    Probe& operator=(const Probe&) = default;
    ~Probe() {
        --g_alive;
        for (int i = 0; i < g_runningDepth; ++i) {
            if (g_running[i] == this) ++g_destroyedWhileRunning;
        }
    }
    template <class E>
    void operator()(const E& e) const {
        // Copy what the call needs first; nothing below reads *this after the action.
        const void* self = this;
        const int t = tag;
        const Action a = action;
        g_running[g_runningDepth++] = self;
        g_log.push_back(Call{t, ValueOf(e)});
        if (a != nullptr) a(t);
        --g_runningDepth;
    }
};

std::string LogText(const std::vector<Call>& log) {
    std::string s = "[";
    for (std::size_t i = 0; i < log.size(); ++i) {
        if (i) s += ", ";
        s += Num(log[i].tag) + ":" + Num(log[i].value);
    }
    return s + "]";
}

// Compares the call log with the expected (tag, value) sequence and clears it.
std::string ExpectCalls(const std::vector<Call>& want, const std::string& what) {
    std::vector<Call> got;
    got.swap(g_log);
    bool same = got.size() == want.size();
    for (std::size_t i = 0; same && i < want.size(); ++i) same = got[i].tag == want[i].tag && got[i].value == want[i].value;
    if (same) return "";
    return what + ": 호출된 핸들러(태그:값) 기대 " + LogText(want) + ", 결과 " + LogText(got);
}

// Handles and bus used by the actions that run inside handlers.
EventBus* g_bus = nullptr;
Subscription g_subs[8];
bool g_nestedDone = false;

void ActResetThird(int) { g_subs[2].Reset(); }
void ActResetSecond(int) { g_subs[1].Reset(); }
void ActResetFirst(int) { g_subs[0].Reset(); }
void ActDropFourthByAssign(int) { g_subs[3] = Subscription(); }
void ActPublishLootThenResetSecond(int) {
    g_bus->Publish(LootEvent{77});
    g_subs[1].Reset();
}
void ActPublishDamageOnce(int) {
    if (g_nestedDone) return;
    g_nestedDone = true;
    g_bus->Publish(DamageEvent{0, 1});
}

std::string PublishMatchesTypeAndOrder() {
    EventBus bus;
    Subscription a = bus.Subscribe<DamageEvent>(Probe(1));
    Subscription heal = bus.Subscribe<HealEvent>(Probe(9));
    Subscription b = bus.Subscribe<DamageEvent>(Probe(2));
    Subscription c = bus.Subscribe<DamageEvent>(Probe(3));
    if (!a.Active() || !b.Active() || !c.Active() || !heal.Active()) return "Subscribe가 반환한 핸들의 Active()가 false";
    if (bus.HandlerCount<DamageEvent>() != 3) return "DamageEvent 핸들러 수 기대 3, 결과 " + Num((long long)bus.HandlerCount<DamageEvent>());
    if (bus.HandlerCount<HealEvent>() != 1) return "HealEvent 핸들러 수 기대 1, 결과 " + Num((long long)bus.HandlerCount<HealEvent>());
    if (bus.HandlerCount<QuestEvent>() != 0) return "구독한 적 없는 QuestEvent의 핸들러 수가 0이 아님";
    bus.Publish(DamageEvent{7, 12});
    std::string d = ExpectCalls({{1, 12}, {2, 12}, {3, 12}}, "DamageEvent 발행");
    if (!d.empty()) return d + " (해당 타입의 핸들러만, 구독 순서대로)";
    bus.Publish(HealEvent{7, 5});
    d = ExpectCalls({{9, 5}}, "HealEvent 발행");
    if (!d.empty()) return d;
    bus.Publish(QuestEvent{4});
    d = ExpectCalls({}, "구독자가 없는 QuestEvent 발행");
    if (!d.empty()) return d;
    int seen = 0;
    const DamageEvent* address = nullptr;
    Subscription e = bus.Subscribe<DamageEvent>([&seen, &address](const DamageEvent& ev) {
        seen += ev.amount;
        address = &ev;
    });
    const DamageEvent hit{3, 40};
    bus.Publish(hit);
    g_log.clear();
    if (seen != 40) return "캡처가 있는 람다 핸들러가 호출되지 않음 (누적 기대 40, 결과 " + Num(seen) + ")";
    if (address != &hit) return "핸들러가 Publish에 넘긴 이벤트 객체가 아닌 복사본을 받음";
    return "";
}

std::string ResetAndDestructor() {
    EventBus bus;
    const int alive0 = g_alive;
    {
        Subscription s = bus.Subscribe<DamageEvent>(Probe(1));
        if (g_alive != alive0 + 1) return "Subscribe 뒤 살아 있는 핸들러 객체 수 기대 1, 결과 " + Num(g_alive - alive0);
        bus.Publish(DamageEvent{1, 5});
        std::string d = ExpectCalls({{1, 5}}, "구독 중 발행");
        if (!d.empty()) return d;
    }
    if (bus.HandlerCount<DamageEvent>() != 0) return "스코프를 벗어나 파괴된 Subscription의 핸들러가 여전히 등록되어 있음";
    if (g_alive != alive0) return "Subscription이 파괴됐는데 핸들러 객체(와 그 캡처)가 파괴되지 않음";
    bus.Publish(DamageEvent{1, 6});
    std::string d = ExpectCalls({}, "구독이 끝난 뒤 발행");
    if (!d.empty()) return d;
    Subscription r = bus.Subscribe<DamageEvent>(Probe(2));
    r.Reset();
    if (r.Active()) return "Reset 뒤에도 Active()가 true";
    if (g_alive != alive0) return "발행 중이 아닐 때 Reset 했는데 핸들러 객체가 즉시 파괴되지 않음";
    r.Reset();
    Subscription empty;
    if (empty.Active()) return "기본 생성한 Subscription의 Active()가 true";
    empty.Reset();
    Subscription k1 = bus.Subscribe<DamageEvent>(Probe(3));
    Subscription k2 = bus.Subscribe<DamageEvent>(Probe(4));
    k1.Reset();
    bus.Publish(DamageEvent{2, 9});
    d = ExpectCalls({{4, 9}}, "두 핸들 중 하나만 Reset 한 뒤 발행");
