    return "";
}

std::string MoveTransfers() {
    if (std::is_copy_constructible<Subscription>::value || std::is_copy_assignable<Subscription>::value)
        return "Subscription을 복사할 수 있음 (한 구독을 두 핸들이 끝낼 수 있게 됨)";
    if (!std::is_nothrow_move_constructible<Subscription>::value || !std::is_nothrow_move_assignable<Subscription>::value)
        return "Subscription의 이동 생성·이동 대입이 noexcept가 아님";
    EventBus bus;
    const int alive0 = g_alive;
    Subscription a = bus.Subscribe<DamageEvent>(Probe(1));
    Subscription b(std::move(a));
    if (a.Active() || !b.Active()) return "이동 생성 뒤 원본은 비고 새 핸들이 활성이어야 함";
    a.Reset();
    bus.Publish(DamageEvent{0, 3});
