#include <cstddef>
#include <utility>
#include <vector>

// A damage-over-time effect on a unit. Poison stacks up to a limit.
struct StatusEffect {
    int id;
    int stacks;
    float remaining;  // seconds left

    StatusEffect(int effectId, float duration) : id(effectId), remaining(duration) {}
};

// Adds one stack (up to maxStacks) and refreshes the duration.
void AddStack(StatusEffect& effect, int maxStacks, float duration) {
    if (effect.stacks < maxStacks) ++effect.stacks;
    effect.remaining = duration;
}

const int kDamageCap = 999999999;  // the UI shows "MAX" for this value

// Damage of a finishing combo: base damage times the number of hits, capped at
// kDamageCap. Both arguments are >= 0.
int ComboDamage(int base, int hits) {
    const int total = base * hits;
    if (total < 0 || total > kDamageCap) return kDamageCap;  // overflow guard
    return total;
}

struct HitRecord {
    int attackerId;
    int damage;
};

struct CombatLog {
    std::vector<std::vector<HitRecord>> rounds;  // one entry per finished round
};

// Moves the hits of the round that just ended into the log without copying them,
// and returns the damage of the round's last hit for the "finishing blow" popup
// (0 if the round had no hits). roundHits is empty afterwards and is reused for
// the next round.
int ArchiveRound(CombatLog& log, std::vector<HitRecord>& roundHits) {
    log.rounds.push_back(std::move(roundHits));
    return roundHits[roundHits.size() - 1].damage;
}

