// How the judge tells the bugs apart. A correct solution passes every case through
// defined behaviour only; none of the instruments below changes what correct code does.
// 1. Checked standard library (_GLIBCXX_DEBUG): libstdc++ checks the precondition of
//    operator[] and back() before the access and, if it is violated, reports on stderr
//    and aborts (SIGABRT). This is documented library behaviour.
//    https://gcc.gnu.org/onlinedocs/libstdc++/manual/debug_mode.html
// 2. -ftrapv for the user code only (#pragma GCC optimize), as an extra signal. On this
//    judge a signed int multiplication in the user code is compiled to a call to libgcc's
//    __mulvsi3, which aborts on overflow. GCC documents the optimize pragma/attribute as
//    a debugging aid, so no case depends on it: every overflow case also compares the
//    result with the exact product computed in 64 bits (inputs are checked, never
//    overflowed, by the reference).
//    https://gcc.gnu.org/onlinedocs/gcc-13.2.0/gcc/Code-Gen-Options.html
// 3. Pattern-filled storage. Reading a member that the constructor left uninitialized is
//    itself undefined behaviour, so no defined test can observe it. The judge builds the
//    object in storage pre-filled with several byte patterns and requires stacks == 0
//    right after construction: a constructor that initializes stacks passes by defined
//    behaviour; one that does not has shown a pattern-dependent value here, which is an
//    observation on this compiler, not a guarantee (the rubric checks the code itself).
#define _GLIBCXX_DEBUG 1
#include <cerrno>
#include <climits>
#include <csignal>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <new>
#include <string>
#include <utility>
#include <vector>
#include <sys/resource.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

#pragma GCC push_options
#pragma GCC optimize("trapv")
#define main __user_main
{{USER_CODE}}
#undef main
#pragma GCC pop_options

namespace judge {

const char* const kCases[] = {
    "effect-starts-with-zero-stacks",
    "effect-stack-limit",
    "combo-damage-in-range",
    "combo-damage-overflow-caps",
    "combo-damage-random-vs-reference",
    "archive-returns-last-hit",
    "archive-empty-round",
    "archive-many-rounds",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

std::string Num(long long v) { return std::to_string(v); }

// Keeps the compiler from assuming anything about the bytes behind p: the pattern
// written before construction really is in memory, and reads after it really load.
inline void Barrier(const void* p) { asm volatile("" : : "r"(p) : "memory"); }

// Builds the object in an opaque function, so the caller cannot see the constructor.
__attribute__((noipa)) StatusEffect* BuildEffect(void* storage, int id, float duration) {
    return new (storage) StatusEffect(id, duration);
}

struct EffectBytes {
    int id;
    int stacks;
    float remaining;
};

// Constructs StatusEffect(id, duration) in storage filled with `pattern` and copies
// out the members (as bytes, through memcpy) right after construction.
EffectBytes ConstructOver(unsigned char pattern, int id, float duration) {
    alignas(StatusEffect) unsigned char storage[sizeof(StatusEffect)];
    std::memset(storage, pattern, sizeof storage);
    Barrier(storage);
    StatusEffect* e = BuildEffect(storage, id, duration);
    Barrier(e);
    EffectBytes out;
    std::memcpy(&out.id, &e->id, sizeof out.id);
    std::memcpy(&out.stacks, &e->stacks, sizeof out.stacks);
    std::memcpy(&out.remaining, &e->remaining, sizeof out.remaining);
    e->~StatusEffect();
    return out;
}

std::string EffectStartsWithZeroStacks() {
    const unsigned char patterns[] = {0x00, 0xA5, 0xFF};
    for (unsigned char p : patterns) {
        const EffectBytes b = ConstructOver(p, 7, 2.5f);
        const std::string at = "저장소를 0x" + std::string(p == 0x00 ? "00" : p == 0xA5 ? "A5" : "FF") + "로 채운 뒤 StatusEffect(7, 2.5f) 생성: ";
        if (b.id != 7) return at + "id 기대 7, 결과 " + Num(b.id);
        if (b.remaining != 2.5f) return at + "remaining이 2.5가 아님";
        if (b.stacks != 0) return at + "stacks 기대 0, 결과 " + Num(b.stacks) + " (생성자가 값을 넣지 않은 멤버를 읽는 것은 미정의 동작이라 어떤 값이 보일지 정해져 있지 않습니다. 채점기는 저장소를 여러 바이트 패턴으로 채워 그 차이를 드러내려 할 뿐입니다)";
    }
    alignas(StatusEffect) unsigned char storage[sizeof(StatusEffect)];
    std::memset(storage, 0xA5, sizeof storage);
    Barrier(storage);
    StatusEffect* e = BuildEffect(storage, 3, 1.0f);
    Barrier(e);
    AddStack(*e, 5, 4.0f);
    const int stacks = e->stacks;
    const float remaining = e->remaining;
    e->~StatusEffect();
    if (stacks != 1) return "새 효과에 AddStack 한 번: stacks 기대 1, 결과 " + Num(stacks);
    if (remaining != 4.0f) return "AddStack 뒤 remaining이 새 지속시간(4.0)으로 갱신되지 않음";
    return "";
}

std::string EffectStackLimit() {
    alignas(StatusEffect) unsigned char storage[sizeof(StatusEffect)];
    std::memset(storage, 0xFF, sizeof storage);
    Barrier(storage);
    StatusEffect* e = BuildEffect(storage, 9, 3.0f);
    Barrier(e);
    std::string reason;
    for (int i = 1; i <= 7 && reason.empty(); ++i) {
        AddStack(*e, 4, 3.0f);
        const int want = i < 4 ? i : 4;
        if (e->stacks != want) reason = "AddStack(최대 4)을 " + Num(i) + "번 호출한 뒤 stacks 기대 " + Num(want) + ", 결과 " + Num(e->stacks);
    }
    e->~StatusEffect();
    return reason;
}

// Reference: exact product in 64 bits, then the cap.
long long ComboReference(int base, int hits) {
    const long long total = static_cast<long long>(base) * static_cast<long long>(hits);
    return total > kDamageCap ? kDamageCap : total;
}

std::string CheckCombo(int base, int hits) {
    const int got = ComboDamage(base, hits);
    const long long want = ComboReference(base, hits);
    if (got != want) return "ComboDamage(" + Num(base) + ", " + Num(hits) + ") 기대 " + Num(want) + ", 결과 " + Num(got);
    return "";
}

std::string ComboDamageInRange() {
    const int pairs[][2] = {{120, 3}, {0, 50}, {77, 0}, {1, 1}, {333333333, 3}, {500000000, 2}, {999999999, 1}, {1000000000, 1}, {31622, 31622}};
    for (const auto& p : pairs) {
        std::string d = CheckCombo(p[0], p[1]);
        if (!d.empty()) return d;
    }
    return "";
}

std::string ComboDamageOverflowCaps() {
    // Each true product is larger than INT_MAX.
    const int pairs[][2] = {{100000, 50000}, {46341, 46341}, {INT_MAX, 2}, {65536, 65536}, {INT_MAX, INT_MAX}, {3, 1431655766}};
    for (const auto& p : pairs) {
        std::string d = CheckCombo(p[0], p[1]);
        if (!d.empty()) return d + " (곱의 실제 값이 int 범위를 넘는 입력)";
    }
    return "";
}

std::string ComboDamageRandom() {
    unsigned seed = 20261122u;
    for (int i = 0; i < 3000; ++i) {
        seed = seed * 1664525u + 1013904223u;
        const unsigned shiftA = (seed >> 27) % 31;
        seed = seed * 1664525u + 1013904223u;
        const int base = static_cast<int>((seed >> 1) >> shiftA);
        seed = seed * 1664525u + 1013904223u;
        const unsigned shiftB = (seed >> 27) % 31;
        seed = seed * 1664525u + 1013904223u;
        const int hits = static_cast<int>((seed >> 1) >> shiftB);
        std::string d = CheckCombo(base, hits);
        if (!d.empty()) return "무작위 " + Num(i) + "번째: " + d;
    }
    return "";
}

std::string Describe(const std::vector<HitRecord>& v) {
    std::string s = "[";
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (i) s += ", ";
        s += Num(v[i].attackerId) + ":" + Num(v[i].damage);
    }
    return s + "]";
}

bool Same(const std::vector<HitRecord>& a, const std::vector<HitRecord>& b) {
    if (a.size() != b.size()) return false;
    for (std::size_t i = 0; i < a.size(); ++i) {
        if (a[i].attackerId != b[i].attackerId || a[i].damage != b[i].damage) return false;
    }
    return true;
}

// Archives one round and checks the return value, the log and the reused vector.
std::string ArchiveOnce(CombatLog& log, std::vector<HitRecord>& hits, const std::string& who) {
    const std::vector<HitRecord> before = hits;
    const std::size_t roundsBefore = log.rounds.size();
    const HitRecord* buffer = hits.empty() ? nullptr : hits.data();
    const int got = ArchiveRound(log, hits);
    const int want = before.empty() ? 0 : before.back().damage;
    if (got != want) return who + ": 반환값(마지막 타격 데미지) 기대 " + Num(want) + ", 결과 " + Num(got);
    if (log.rounds.size() != roundsBefore + 1) return who + ": 기록된 라운드 수 기대 " + Num((long long)roundsBefore + 1) + ", 결과 " + Num((long long)log.rounds.size());
    if (!Same(log.rounds.back(), before)) return who + ": 기록된 타격 기대 " + Describe(before) + ", 결과 " + Describe(log.rounds.back());
    if (buffer != nullptr && log.rounds.back().data() != buffer)
        return who + ": 타격 기록을 옮기지 않고 복사함 (기록된 vector의 버퍼가 원래 버퍼와 다름)";
    if (!hits.empty()) return who + ": 호출 뒤 roundHits가 비어 있지 않음 (원소 " + Num((long long)hits.size()) + "개)";
    return "";
}

std::string ArchiveReturnsLastHit() {
    CombatLog log;
    std::vector<HitRecord> hits = {{1, 10}, {2, 25}, {3, 7}};
    return ArchiveOnce(log, hits, "타격 3개인 라운드");
}

std::string ArchiveEmptyRound() {
    CombatLog log;
    std::vector<HitRecord> hits;
    std::string d = ArchiveOnce(log, hits, "타격이 없는 라운드");
    if (!d.empty()) return d;
    hits.push_back(HitRecord{4, 99});
    d = ArchiveOnce(log, hits, "빈 라운드 다음, 타격 1개인 라운드");
    if (!d.empty()) return d;
    std::vector<HitRecord> again;
    return ArchiveOnce(log, again, "다시 빈 라운드");
}

std::string ArchiveManyRounds() {
    CombatLog log;
    std::vector<HitRecord> hits;  // reused every round, as the game does
    unsigned seed = 77u;
    for (int round = 0; round < 40; ++round) {
        seed = seed * 1664525u + 1013904223u;
        const int n = static_cast<int>((seed >> 16) % 6);
        for (int i = 0; i < n; ++i) {
            seed = seed * 1664525u + 1013904223u;
            hits.push_back(HitRecord{i + 1, static_cast<int>((seed >> 12) % 5000)});
        }
        std::string d = ArchiveOnce(log, hits, "라운드 " + Num(round) + "(타격 " + Num(n) + "개)");
        if (!d.empty()) return d;
    }
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    EffectStartsWithZeroStacks, EffectStackLimit,     ComboDamageInRange, ComboDamageOverflowCaps,
    ComboDamageRandom,          ArchiveReturnsLastHit, ArchiveEmptyRound, ArchiveManyRounds,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                      : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

// ---- process isolation: every case runs in its own child process ----

volatile std::sig_atomic_t g_current = 0;

// Only used when the judge cannot run a case in its own process (see main).
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (오버플로 검사나 범위 검사에 걸렸을 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 1;  // a correct case finishes in milliseconds
const int kMaxTimeouts = 3;       // after this many, the remaining cases are not started

// Why a case process ended without writing a verdict. Which instrument aborted
// depends on the case: the combo cases only do int arithmetic, the archive cases
// touch vectors.
std::string DeathReason(int i, int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT && i >= 2 && i <= 4)
            return "비정상 종료(SIGABRT): 사용자 코드에 보조 신호로 켠 -ftrapv 검사가 넘친 부호 있는 int 연산을 잡은 것으로 보입니다 (넘친 뒤에 검사하지 말고, 넘치기 전에 확인하거나 더 넓은 타입으로 계산하세요)";
        if (sig == SIGABRT && i >= 5)
            return "표준 라이브러리 검사 모드가 operator[]나 back()의 전제 조건 위반(빈 vector, 범위 밖 인덱스)을 감지해 중단함(SIGABRT) (이동한 뒤의 vector를 읽고 있지 않은지 확인)";
        if (sig == SIGABRT) return "비정상 종료(SIGABRT): 오버플로 검사나 표준 라이브러리 검사에 걸렸을 가능성";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음 (끝나지 않는 루프 가능성)";
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료";
        if (sig == SIGKILL) return "실행 환경이 프로세스를 강제 종료함 (메모리 한도 초과 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Checked-library reports are word-wrapped at about 78 columns by default. In
    // libstdc++ 13 a single word of exactly 77 columns (a long type name, for example)
    // makes that wrapping print blank lines until the process is killed (reproduced on
    // this judge). A large GLIBCXX_DEBUG_MESSAGE_LENGTH, a variable the libstdc++ manual
    // documents, turns the wrapping off in practice.
    setenv("GLIBCXX_DEBUG_MESSAGE_LENGTH", "100000", 1);
    int timeouts = 0;
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        if (timeouts >= kMaxTimeouts) {
            const std::string skipped = std::string("[FAIL] ") + kCases[i] + " :: 앞선 케이스 " + Num(timeouts) +
                                        "개가 시간 초과되어 이 케이스는 실행하지 않음 (끝나지 않는 루프를 먼저 고치세요)\n";
            Emit(skipped.c_str());
            continue;
        }
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            struct rlimit memory;
            memory.rlim_cur = memory.rlim_max = static_cast<rlim_t>(256) * 1024 * 1024;
            setrlimit(RLIMIT_AS, &memory);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            // No process isolation available: run in this process. A crash then ends the
            // run, and OnCrash still writes one line for every remaining case.
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        if (waited == pid && WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) ++timeouts;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(i, waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written
}

