#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <type_traits>

// One live particle. The effect system keeps up to 100,000 of these in a std::vector.
// Members are grouped by alignment, largest first, so no member needs padding in front
// of it; only the tail is padded up to a multiple of alignof(ParticleState).
struct ParticleState {
    double age;           // seconds since spawn          (8-byte alignment)
    float x, y, z;        // world position                (4-byte alignment)
    float size;
    std::uint16_t frame;  // flipbook frame                (2-byte alignment)
    bool alive;           //                               (1-byte alignment)
    bool looping;
    std::uint8_t layer;   // sorting layer
};

// Sizes and alignments are implementation-defined. These values hold on the judge
// (GCC 13.2, x86-64 Linux, System V ABI); the assertions make a different target fail
// to compile instead of silently changing the layout.
static_assert(std::is_standard_layout<ParticleState>::value, "offsetof needs a standard-layout type");
static_assert(sizeof(double) + 4 * sizeof(float) + sizeof(std::uint16_t) + 2 * sizeof(bool) + sizeof(std::uint8_t) == 29,
              "member sizes add up to 29 bytes here");
static_assert(alignof(ParticleState) == 8, "the double sets the alignment");
static_assert(sizeof(ParticleState) == 32, "29 bytes of members rounded up to a multiple of 8");
static_assert(offsetof(ParticleState, x) == 8 && offsetof(ParticleState, size) == 20, "no padding after age");
static_assert(offsetof(ParticleState, frame) == 24 && offsetof(ParticleState, layer) == 28, "small members packed at the end");

int main() {
    std::printf("sizeof %zu, alignof %zu\n", sizeof(ParticleState), alignof(ParticleState));
    std::printf("offsets: alive %zu, age %zu, looping %zu, x %zu, y %zu, z %zu, frame %zu, size %zu, layer %zu\n",
                offsetof(ParticleState, alive), offsetof(ParticleState, age), offsetof(ParticleState, looping),
                offsetof(ParticleState, x), offsetof(ParticleState, y), offsetof(ParticleState, z),
                offsetof(ParticleState, frame), offsetof(ParticleState, size), offsetof(ParticleState, layer));
    std::printf("100000 particles: %zu bytes\n", sizeof(ParticleState) * 100000);
    return 0;
}

