problems.solutionCode:
#include <cstddef>
#include <new>
#include <stdexcept>
#include <utility>

// Growable array for engine code. Unused capacity holds no objects: an element is
// constructed when it is added and destroyed when it is removed.
template <class T>
class DynArray {
public:
    DynArray() noexcept = default;

    ~DynArray() {
        clear();
        Release(data_);
    }

    DynArray(const DynArray&) = delete;
    DynArray& operator=(const DynArray&) = delete;

    void push_back(const T& value) { emplace_back(value); }
    void push_back(T&& value) { emplace_back(std::move(value)); }

    // Constructs a new last element from args and returns it.
    template <class... Args>
    T& emplace_back(Args&&... args) {
        if (size_ < capacity_) {
            T* slot = ::new (static_cast<void*>(data_ + size_)) T(std::forward<Args>(args)...);
            ++size_;
            return *slot;
        }
        // Full. args may refer to one of our own elements (v.push_back(v[0])), so the
        // new element is built in the new buffer while the old one is still intact.
        const std::size_t newCapacity = GrownCapacity();
        T* fresh = Allocate(newCapacity);
        try {
            ::new (static_cast<void*>(fresh + size_)) T(std::forward<Args>(args)...);
        } catch (...) {
            Release(fresh);
            throw;
        }
        try {
            MoveElementsTo(fresh);
        } catch (...) {
            fresh[size_].~T();
            Release(fresh);
            throw;
        }
        AdoptBuffer(fresh, newCapacity);
        return data_[size_++];
    }

    // Destroys the last element. Precondition: !empty().
    void pop_back() {
        --size_;
        data_[size_].~T();
    }

    // Destroys every element; the capacity stays the same.
    void clear() noexcept {
        DestroyRange(data_, size_);
        size_ = 0;
    }

    // Makes room for at least newCapacity elements without constructing any.
    void reserve(std::size_t newCapacity) {
        if (newCapacity <= capacity_) return;
        if (newCapacity > MaxCapacity()) throw std::length_error("DynArray::reserve: too large");
        T* fresh = Allocate(newCapacity);
        try {
            MoveElementsTo(fresh);
        } catch (...) {
            Release(fresh);
            throw;
        }
        AdoptBuffer(fresh, newCapacity);
    }

    std::size_t size() const noexcept { return size_; }
    std::size_t capacity() const noexcept { return capacity_; }
    bool empty() const noexcept { return size_ == 0; }

    T& operator[](std::size_t i) noexcept { return data_[i]; }
    const T& operator[](std::size_t i) const noexcept { return data_[i]; }

private:
    static std::size_t MaxCapacity() noexcept { return static_cast<std::size_t>(-1) / sizeof(T); }

    // Geometric growth (x2) keeps push_back amortized O(1).
    std::size_t GrownCapacity() const {
        if (capacity_ == 0) return 1;
        if (capacity_ > MaxCapacity() / 2) throw std::length_error("DynArray: too large");
        return capacity_ * 2;
    }

    // Raw storage: no T is constructed here.
    static T* Allocate(std::size_t n) { return static_cast<T*>(::operator new(n * sizeof(T))); }
    static void Release(T* p) noexcept { ::operator delete(static_cast<void*>(p)); }

    static void DestroyRange(T* first, std::size_t n) noexcept {
        while (n > 0) first[--n].~T();
    }

    // Constructs the current elements in fresh: moved when T's move constructor is
    // noexcept (or T cannot be copied), copied otherwise, like std::vector. If a copy
    // throws, the copies made so far are destroyed and the old elements are untouched.
    void MoveElementsTo(T* fresh) {
        std::size_t built = 0;
        try {
            for (; built < size_; ++built) {
                ::new (static_cast<void*>(fresh + built)) T(std::move_if_noexcept(data_[built]));
            }
        } catch (...) {
            DestroyRange(fresh, built);
            throw;
        }
    }

    // The elements already live in fresh: end the old ones and switch buffers.
    void AdoptBuffer(T* fresh, std::size_t newCapacity) noexcept {
        DestroyRange(data_, size_);
        Release(data_);
        data_ = fresh;
        capacity_ = newCapacity;
    }

    T* data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t capacity_ = 0;
};

