#include <unistd.h>

// Counting, quarantining heap. Every block from operator new is counted until it is
// released (the leak checks use this). Released memory is overwritten with 0xDD and
// never handed out again, so a wrong solution that reads a freed buffer does not see a
// different value on every run; no verdict depends on what such a read returns.
namespace judge_heap {
const std::size_t kHeader = 16;
long long g_liveBlocks = 0;
}
void* operator new(std::size_t n) {
    unsigned char* raw = static_cast<unsigned char*>(std::malloc(n + judge_heap::kHeader));
    if (raw == nullptr) throw std::bad_alloc();
    std::memcpy(raw, &n, sizeof(n));
    ++judge_heap::g_liveBlocks;
    return raw + judge_heap::kHeader;
}
void* operator new[](std::size_t n) { return operator new(n); }
void operator delete(void* p) noexcept {
    if (p == nullptr) return;
    std::size_t n = 0;
    std::memcpy(&n, static_cast<unsigned char*>(p) - judge_heap::kHeader, sizeof(n));
    std::memset(p, 0xDD, n);
    --judge_heap::g_liveBlocks;
}
void operator delete[](void* p) noexcept { operator delete(p); }
void operator delete(void* p, std::size_t) noexcept { operator delete(p); }
void operator delete[](void* p, std::size_t) noexcept { operator delete(p); }

namespace judge_types {
struct Counts {
    long long live, constructed, destroyed, copies, moves;
    long long badSource;   // copied or moved from an object that is not alive
    long long badDestroy;  // destructor run on an object that is not alive
};
Counts g{};

// Addresses of the Tracked objects alive right now (linear probing, no heap use).
// Tracked asks this table whether an object is alive before it reads that object, so
// using a destroyed element or a freed buffer is detected by comparing addresses,
// never by reading dead memory.
const std::size_t kSlots = std::size_t(1) << 16;
std::uintptr_t g_liveAt[kSlots];  // 0 = free slot
std::size_t Home(std::uintptr_t a) { return static_cast<std::size_t>((a >> 2) * 0x9E3779B97F4A7C15ull >> 48); }
std::size_t Find(std::uintptr_t a) {  // slot holding a, or the free slot where it would go
    std::size_t i = Home(a);
    while (g_liveAt[i] != 0 && g_liveAt[i] != a) i = (i + 1) & (kSlots - 1);
    return i;
}
bool IsLive(const void* p) { const std::uintptr_t a = reinterpret_cast<std::uintptr_t>(p); return g_liveAt[Find(a)] == a; }
void Born(const void* p) { const std::uintptr_t a = reinterpret_cast<std::uintptr_t>(p); g_liveAt[Find(a)] = a; ++g.live; ++g.constructed; }
void Died(const void* p) {  // removes p, then closes the gap (backward-shift deletion)
    std::size_t i = Find(reinterpret_cast<std::uintptr_t>(p));
    g_liveAt[i] = 0;
    for (std::size_t j = (i + 1) & (kSlots - 1); g_liveAt[j] != 0; j = (j + 1) & (kSlots - 1)) {
        const std::size_t k = Home(g_liveAt[j]);
        const bool stays = i <= j ? (i < k && k <= j) : (i < k || k <= j);
        if (stays) continue;
        g_liveAt[i] = g_liveAt[j];
        g_liveAt[j] = 0;
        i = j;
    }
    --g.live; ++g.destroyed;
}
const int kFromDeadObject = -2147483647;  // value given to a copy of an object that was not alive

// Instrumented element. It has no default constructor, so storage for unused
// capacity cannot be a T[] array.
struct Tracked {
    int value;
    static int SourceValue(const Tracked& o) {
        if (IsLive(&o)) return o.value;
        ++g.badSource;
        return kFromDeadObject;
    }
    explicit Tracked(int v) : value(v) { Born(this); }
    Tracked(const Tracked& o) : value(SourceValue(o)) { Born(this); ++g.copies; }
    Tracked(Tracked&& o) noexcept : value(SourceValue(o)) {
        if (IsLive(&o)) o.value = -1;
        Born(this); ++g.moves;
    }
    Tracked& operator=(const Tracked& o) {
        if (!IsLive(this) || !IsLive(&o)) { ++g.badSource; return *this; }
        value = o.value;
        return *this;
    }
    Tracked& operator=(Tracked&& o) noexcept {
        if (!IsLive(this) || !IsLive(&o)) { ++g.badSource; return *this; }
        value = o.value;
        o.value = -1;
        return *this;
    }
    ~Tracked() {
        if (!IsLive(this)) { ++g.badDestroy; return; }
        Died(this);
    }
};

// Move-only element (it owns a heap int).
struct MoveOnly {
    std::unique_ptr<int> p;
    explicit MoveOnly(int v) : p(new int(v)) {}
};
}  // namespace judge_types

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {
using judge_types::Tracked;
using judge_types::MoveOnly;
using judge_types::g;

const char* const kCases[] = {
    "push-emplace-index",
    "reserve-constructs-nothing",
    "each-element-destroyed-once",
    "growth-is-geometric",
    "growth-moves-not-copies",
    "push-back-own-element",
    "strings-no-leak",
    "random-vs-std-vector",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

std::string Num(long long v) { return std::to_string(v); }

// Last element through the public interface only (DynArray has no back()).
template <class T>
T& Back(DynArray<T>& v) { return v[v.size() - 1]; }

// Problems that the counters can see. Empty string when everything is consistent.
std::string CountsProblem(const std::string& at) {
    if (g.badSource != 0) return at + ": 파괴된(또는 해제된) 원소를 복사·이동·대입함 " + Num(g.badSource) + "회";
    if (g.badDestroy != 0) return at + ": 살아 있지 않은 원소의 소멸자를 호출함 " + Num(g.badDestroy) + "회 (이중 파괴 또는 생성하지 않은 칸 파괴)";
    return "";
}

std::string PushEmplaceIndex() {
    DynArray<int> v;
    if (!v.empty() || v.size() != 0) return "새 DynArray가 비어 있지 않음";
    const int seven = 7;
    v.push_back(seven);
    v.push_back(8);
    int& r = v.emplace_back(9);
    if (v.size() != 3) return "push_back 2번 + emplace_back 1번 뒤 size 기대 3, 결과 " + Num((long long)v.size());
    if (&r != &v[2]) return "emplace_back이 새로 만든 마지막 원소의 참조를 반환하지 않음";
    if (v[0] != 7 || v[1] != 8 || v[2] != 9) return "원소 값 기대 [7, 8, 9], 결과 [" + Num(v[0]) + ", " + Num(v[1]) + ", " + Num(v[2]) + "]";
    r = 90;
    if (v[2] != 90) return "emplace_back이 반환한 참조로 고친 값이 배열에 반영되지 않음";
    if (v.capacity() < v.size()) return "capacity가 size보다 작음";
    const DynArray<int>& cv = v;
    if (cv[1] != 8) return "const operator[]가 잘못된 값을 반환함";
    DynArray<std::pair<int, std::string>> named;
    named.emplace_back(3, "slime");
    named.emplace_back(4, std::string(40, 'x'));
    if (named.size() != 2 || named[0].first != 3 || named[0].second != "slime" || named[1].second.size() != 40)
        return "emplace_back이 인자 여러 개로 원소를 만들지 못함 (pair<int, string>)";
    for (int i = 0; i < 100; ++i) v.push_back(i);
    for (int i = 0; i < 100; ++i) {
        if (v[3 + i] != i) return "103개를 넣은 뒤 인덱스 " + Num(3 + i) + " 값 기대 " + Num(i) + ", 결과 " + Num(v[3 + i]);
    }
    return "";
}

std::string ReserveConstructsNothing() {
    g = judge_types::Counts{};  // every case runs in a fresh process, so the live table starts empty
    {
        DynArray<Tracked> v;
        v.reserve(100);
        if (v.capacity() < 100) return "reserve(100) 뒤 capacity 기대 100 이상, 결과 " + Num((long long)v.capacity());
        if (v.size() != 0) return "reserve가 size를 바꿈";
        if (g.constructed != 0) return "reserve(100)이 원소를 " + Num(g.constructed) + "개 생성함 (남는 용량에는 객체가 없어야 함)";
        for (int i = 0; i < 30; ++i) v.emplace_back(i);
        if (g.live != 30) return "30개를 넣은 뒤 살아 있는 원소 기대 30, 결과 " + Num(g.live);
        if (g.copies != 0) return "용량이 충분한데 emplace_back이 원소를 복사함 " + Num(g.copies) + "회";
        const std::size_t cap = v.capacity();
        const long long moves0 = g.moves;
        v.reserve(10);
        if (v.capacity() != cap) return "현재 용량보다 작은 reserve(10)가 capacity를 바꿈";
        if (g.moves != moves0) return "현재 용량보다 작은 reserve(10)가 원소를 옮김";
        for (int i = 0; i < 30; ++i) {
            if (v[i].value != i) return "reserve 뒤 원소 값이 바뀜";
        }
        v.reserve(500);
        if (v.capacity() < 500 || v.size() != 30) return "reserve(500) 뒤 size·capacity가 기대와 다름";
        for (int i = 0; i < 30; ++i) {
            if (v[i].value != i) return "용량을 늘린 reserve 뒤 원소 값 기대 " + Num(i) + ", 결과 " + Num(v[i].value);
        }
        if (g.live != 30) return "용량을 늘린 reserve 뒤 살아 있는 원소 기대 30, 결과 " + Num(g.live);
        if (g.copies != 0) return "noexcept 이동이 가능한 원소를 reserve가 복사함 " + Num(g.copies) + "회";
    }
    if (g.live != 0) return "DynArray 파괴 뒤 살아 있는 원소 " + Num(g.live) + "개";
    return CountsProblem("reserve");
}

std::string EachElementDestroyedOnce() {
    g = judge_types::Counts{};
    const long long blocks0 = judge_heap::g_liveBlocks;
    {
        DynArray<Tracked> v;
        for (int i = 0; i < 20; ++i) v.push_back(Tracked(i));
        if (g.live != 20) return "20개를 넣은 뒤 살아 있는 원소 기대 20, 결과 " + Num(g.live);
        v.pop_back();
        v.pop_back();
        if (g.live != 18 || v.size() != 18) return "pop_back 2번 뒤 살아 있는 원소·size 기대 18, 결과 " + Num(g.live) + "·" + Num((long long)v.size());
        if (v[17].value != 17) return "pop_back 뒤 마지막 원소 값 기대 17, 결과 " + Num(v[17].value);
        const std::size_t cap = v.capacity();
        v.clear();
        if (g.live != 0 || v.size() != 0) return "clear 뒤에도 원소가 살아 있음 (" + Num(g.live) + "개)";
        if (v.capacity() != cap) return "clear가 capacity를 바꿈 (기대 " + Num((long long)cap) + ", 결과 " + Num((long long)v.capacity()) + ")";
        for (int i = 0; i < 5; ++i) v.emplace_back(100 + i);
        if (v.size() != 5 || v[4].value != 104) return "clear 뒤 다시 넣은 원소가 잘못됨";
        std::string d = CountsProblem("pop_back·clear");
        if (!d.empty()) return d;
    }
    if (g.live != 0) return "DynArray 소멸자가 원소 " + Num(g.live) + "개를 파괴하지 않음";
    if (g.destroyed != g.constructed) return "생성 " + Num(g.constructed) + "회, 파괴 " + Num(g.destroyed) + "회 (같아야 함)";
    if (judge_heap::g_liveBlocks != blocks0) return "DynArray가 파괴된 뒤에도 해제되지 않은 메모리 블록 " + Num(judge_heap::g_liveBlocks - blocks0) + "개";
    return CountsProblem("소멸자");
}

std::string GrowthIsGeometric() {
    DynArray<int> v;
    std::size_t cap = v.capacity();
    int growths = 0;
    for (int i = 0; i < 100000; ++i) {
        v.push_back(i);
        if (v.capacity() < v.size()) return "push_back " + Num(i + 1) + "번째에서 capacity(" + Num((long long)v.capacity()) + ")가 size보다 작음";
        if (v.capacity() != cap) {
            const std::size_t now = v.capacity();
            if (now < cap + cap / 2) return "용량이 " + Num((long long)cap) + "에서 " + Num((long long)now) + "로 늘어남 (기존 용량의 1.5배 이상이어야 분할 상환 O(1))";
            cap = now;
            ++growths;
        }
    }
    for (int i = 0; i < 100000; i += 997) {
        if (v[i] != i) return "100000개를 넣은 뒤 인덱스 " + Num(i) + "의 값이 틀림";
    }
    if (growths > 60) return "100000개를 넣는 동안 재할당 " + Num(growths) + "회";
    return "";
}

std::string GrowthMovesNotCopies() {
    g = judge_types::Counts{};
    {
        DynArray<Tracked> v;
        const int n = 3000;
        for (int i = 0; i < n; ++i) v.push_back(Tracked(i));
        if (g.copies != 0) return "noexcept 이동 생성자가 있는 원소를 넣고 늘리는 동안 복사가 " + Num(g.copies) + "번 일어남 (재할당 때는 이동해야 함)";
        if (g.moves > 6LL * n) return "원소 " + Num(n) + "개를 넣는 동안 이동이 " + Num(g.moves) + "번 (너무 많음: 재할당이 기하급수적이지 않거나 원소를 여러 번 옮김)";
        const Tracked keep(5);
        const long long copies0 = g.copies;
        for (int i = 0; i < 10; ++i) v.push_back(keep);
        if (g.copies - copies0 != 10) return "lvalue push_back 10번 동안 복사 기대 10회, 결과 " + Num(g.copies - copies0) + "회";
        for (int i = 0; i < n; ++i) {
            if (v[i].value != i) return "재할당 뒤 인덱스 " + Num(i) + " 값 기대 " + Num(i) + ", 결과 " + Num(v[i].value);
        }
        std::string d = CountsProblem("재할당");
        if (!d.empty()) return d;
    }
    if (g.live != 0) return "파괴 뒤 살아 있는 원소 " + Num(g.live) + "개";
    DynArray<MoveOnly> owners;
    for (int i = 0; i < 200; ++i) {
        MoveOnly m(i);
        owners.push_back(std::move(m));
    }
    owners.emplace_back(200);
    for (int i = 0; i <= 200; ++i) {
        if (!owners[i].p || *owners[i].p != i) return "이동만 가능한 원소(unique_ptr 멤버)가 재할당 뒤 인덱스 " + Num(i) + "에서 값을 잃음";
    }
    return "";
}

std::string PushBackOwnElement() {
    g = judge_types::Counts{};
    {
        DynArray<Tracked> v;
        v.emplace_back(41);
        int round = 0;
        while (round < 6) {
            while (v.size() < v.capacity()) v.emplace_back(static_cast<int>(v.size()) + 100);
            // Full: the next push_back must reallocate while its argument lives in the old buffer.
            const int first = v[0].value;
            v.push_back(v[0]);
            if (Back(v).value != first) return "가득 찬 배열에 v.push_back(v[0]): 새 원소 값 기대 " + Num(first) + ", 결과 " + Num(Back(v).value) + " (인자가 옛 버퍼의 원소를 가리킴)";
            std::string d = CountsProblem("v.push_back(v[0])");
            if (!d.empty()) return d;
            while (v.size() < v.capacity()) v.emplace_back(-5);
            const int lastValue = v[v.size() - 1].value;
            const Tracked& lastRef = v[v.size() - 1];
            v.push_back(lastRef);
            if (Back(v).value != lastValue) return "가득 찬 배열에 마지막 원소를 push_back: 새 원소 값 기대 " + Num(lastValue) + ", 결과 " + Num(Back(v).value);
            d = CountsProblem("v.push_back(v.back())");
            if (!d.empty()) return d;
            ++round;
        }
    }
    if (g.live != 0) return "파괴 뒤 살아 있는 원소 " + Num(g.live) + "개";
    return "";
}

std::string StringsNoLeak() {
    const long long blocks0 = judge_heap::g_liveBlocks;
    {
        DynArray<std::string> names;
        for (int i = 0; i < 300; ++i) names.push_back(std::string(48, static_cast<char>('a' + i % 26)) + std::to_string(i));
        for (int i = 0; i < 40; ++i) names.pop_back();
        const std::string lastExpected = std::string(48, static_cast<char>('a' + 259 % 26)) + std::to_string(259);
        if (names.size() != 260 || names[259] != lastExpected) return "긴 문자열 300개를 넣고 40개를 뺀 뒤 마지막 원소가 틀림";
        for (int i = 0; i < 260; i += 13) {
            const std::string want = std::string(48, static_cast<char>('a' + i % 26)) + std::to_string(i);
            if (names[i] != want) return "재할당 뒤 문자열 " + Num(i) + "번 원소가 바뀜";
        }
        names.clear();
        for (int i = 0; i < 10; ++i) names.emplace_back(64, 'z');
    }
    const long long leaked = judge_heap::g_liveBlocks - blocks0;
    if (leaked != 0) return "DynArray<std::string>을 파괴한 뒤 해제되지 않은 메모리 블록 " + Num(leaked) + "개 (원소의 소멸자나 버퍼 해제가 빠짐)";
    return "";
}

std::string RandomVsStdVector() {
    g = judge_types::Counts{};
    {
        DynArray<Tracked> v;
        std::vector<int> ref;
        unsigned seed = 20261122u;
        for (int step = 0; step < 4000; ++step) {
            seed = seed * 1664525u + 1013904223u;
            const unsigned op = (seed >> 16) % 20;
            const int value = static_cast<int>((seed >> 4) % 100000);
            if (op < 6) {
                const Tracked t(value);
                v.push_back(t);
                ref.push_back(value);
            } else if (op < 11) {
                v.push_back(Tracked(value));
                ref.push_back(value);
            } else if (op < 15) {
                v.emplace_back(value);
                ref.push_back(value);
            } else if (op < 18) {
                if (!ref.empty()) {
                    v.pop_back();
                    ref.pop_back();
                }
            } else if (op < 19) {
                v.reserve(static_cast<std::size_t>(value % 300));
            } else if ((seed >> 8) % 8 == 0) {
                v.clear();
                ref.clear();
            }
            const std::string at = "step " + Num(step);
            if (v.size() != ref.size()) return at + ": size 기대 " + Num((long long)ref.size()) + ", 결과 " + Num((long long)v.size());
            if (v.capacity() < v.size()) return at + ": capacity가 size보다 작음";
            if (g.live != static_cast<long long>(ref.size())) return at + ": 살아 있는 원소 기대 " + Num((long long)ref.size()) + ", 결과 " + Num(g.live);
            if (!ref.empty() && Back(v).value != ref.back()) return at + ": 마지막 원소 값 기대 " + Num(ref.back()) + ", 결과 " + Num(Back(v).value);
            if (step % 97 == 0) {
                for (std::size_t i = 0; i < ref.size(); ++i) {
                    if (v[i].value != ref[i]) return at + ": 인덱스 " + Num((long long)i) + " 값 기대 " + Num(ref[i]) + ", 결과 " + Num(v[i].value);
                }
            }
            std::string d = CountsProblem(at);
            if (!d.empty()) return d;
        }
    }
    if (g.live != 0) return "파괴 뒤 살아 있는 원소 " + Num(g.live) + "개";
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    PushEmplaceIndex,     ReserveConstructsNothing, EachElementDestroyedOnce, GrowthIsGeometric,
    GrowthMovesNotCopies, PushBackOwnElement,       StringsNoLeak,            RandomVsStdVector,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                      : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

// ---- process isolation: every case runs in its own child process ----

volatile std::sig_atomic_t g_current = 0;

// Only used when the judge cannot run a case in its own process (see main).
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (해제된 버퍼나 용량 밖 칸에 접근했을 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 1;  // a correct case finishes in milliseconds
const int kMaxTimeouts = 3;       // after this many, the remaining cases are not started

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료 (해제된 버퍼, 용량 밖의 칸, 생성하지 않은 원소에 접근했을 가능성)";
        if (sig == SIGABRT) return "비정상 종료(SIGABRT): 할당자가 힙 손상을 감지했을 가능성 (용량보다 많은 원소를 썼는지 확인)";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음 (끝나지 않는 루프, 또는 재할당이 너무 잦음)";
        if (sig == SIGKILL) return "실행 환경이 프로세스를 강제 종료함 (메모리 한도 초과 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    int timeouts = 0;
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        if (timeouts >= kMaxTimeouts) {
            const std::string skipped = std::string("[FAIL] ") + kCases[i] + " :: 앞선 케이스 " + Num(timeouts) +
                                        "개가 시간 초과되어 이 케이스는 실행하지 않음 (끝나지 않는 루프를 먼저 고치세요)\n";
            Emit(skipped.c_str());
            continue;
        }
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            struct rlimit memory;
            memory.rlim_cur = memory.rlim_max = static_cast<rlim_t>(512) * 1024 * 1024;
            setrlimit(RLIMIT_AS, &memory);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            // No process isolation available: run in this process. A crash then ends the
            // run, and OnCrash still writes one line for every remaining case.
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        if (waited == pid && WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) ++timeouts;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written
}
